    def calibration_hydrograph_bootstraping_show(self,type_calibration):
        """Method to make the bootstraping for the calibrated hydrograph and show dialog"""
        #Obtain data
        if type_calibration == "hydrograph":
            path = self.obtain_direction_vfsmod(self.dlg_calibration_results_hydrograph.results.text())
        elif type_calibration == "sedimentograph":
            path = self.obtain_direction_vfsmod(self.dlg_calibration_results_sedimentograph.results.text())
        if os.path.exists(path) and os.path.isfile(path):    
            #First add the text
            with open(path, "r") as archivo:
                lineas = archivo.readlines()
            contenido = ""
            times = []
            observed = []
            simulated = []
            for k,i in enumerate(lineas):
                if i[:4]=="Time":
                    for m in range(k+1,len(lineas)):
                        try:
                            times.append(float(lineas[m].split(",")[0]))
                        except:
                            times.append(0)
                        try:
                            observed.append(float(lineas[m].split(",")[1]))
                        except:
                            observed.append(0)
                        try:
                            simulated.append(float(lineas[m].split(",")[2]))
                        except:
                            simulated.append(0)
                    break
                contenido += i
            
            
            #Obtain the expected length of block for the stationary bootsrapping according to Automatic Block-Length Selection for the Dependent Bootstrap (Dimitris N. Politis1 and Halbert White)
            def lambda_function(t):
                if abs(t)>=0 and abs(t)<=0.5:
                    return 1
                elif abs(t)>=0.5 and abs(t)<=1:
                    return 2*(1-abs(t))
                else:
                    0

            def r_function(k):
                n = len(observed)
                average = np.sum(observed)/len(observed)
                values = 0
                for i in range(n-abs(k)):
                    values += (observed[i]-average)/(observed[i+abs(k)]-average)
                return values/n


            def g_function(w):
                values = 0
                for i in range(-M,M):
                    values += lambda_function(i/M)*r_function(i)*math.cos(w*i)
                return values


            #Calculate G
            M = int(len(observed)/2)
            G = 0
            for i in range(-M,M):
                G += lambda_function(i/M)*abs(i)*r_function(i)

            #Calculate D
            integration_step = 0.1
            D = 4*(g_function(0)**2)
            values = 0
            w = -math.pi
            while w<math.pi:
                values += (1+math.cos(w))*(g_function(w)**2)*integration_step
                w += integration_step

            values = 2*values/math.pi
            D = D + values

            #Calculate optimal size of block
            b = (((2*(G**2))/D)**(1/3))*(len(observed)**(1/3))

            #Calculate probability for geometrical distribution after we calculated the expected length
            p = 1/b
            #if pequal or same as 1 then there is not distribution
            if p>=1: p = 0.9
            
            #Do the bootstrapping
            number_resamplings = 2000
            nash_list = []
            rmse_list = []
            for i in range(number_resamplings):
                observed_blocks = []
                simulated_blocks = []
                while len(observed_blocks)<len(observed):
                    index = np.random.randint(0, len(observed), dtype=int)
                    size = geom.rvs(p, size=1)[0]
                    if index+size>=len(observed):
                        block_observed = list(observed[index:])+list(observed[:(index+size)%len(observed)])
                        block_simulated = list(simulated[index:])+list(simulated[:(index+size)%len(simulated)])
                    else:
                        block_observed = list(observed[index:index+size])
                        block_simulated = list(simulated[index:index+size])
                        
                    observed_blocks += block_observed
                    simulated_blocks += block_simulated
                    
                observed_blocks = observed_blocks[:len(observed)]
                simulated_blocks = simulated_blocks[:len(simulated)]
                
                #Obtain indicators values
                observed_sample = np.array(observed_blocks)
                simulated_sample = np.array(simulated_blocks)
                #Caclulate nash
                mean_observed = np.mean(observed_sample)
                numerator = np.sum((observed_sample - simulated_sample) ** 2)
                denominator = np.sum((observed_sample - mean_observed) ** 2)
                nse = 1 - (numerator / denominator)
                nash_list.append(nse)
                #Calculate RMSE
                rmse = np.sqrt(np.mean((observed_sample - simulated_sample) ** 2))
                rmse_list.append(rmse)
            
            
            #Create variable to be obtained in other method
            if type_calibration == "hydrograph":
                self.nashes_bootstraping_hydrograph = nash_list
                self.rmse_bootstraping_hydrograph = rmse_list
            elif type_calibration == "sedimentograph":
                self.nashes_bootstraping_sedimentograph = nash_list
                self.rmse_bootstraping_sedimentograph = rmse_list
            
            #Update graph
            self.calibration_hydrograph_bootstraping_update(type_calibration)
            
            #Show dialog
            if type_calibration == "hydrograph":
                self.dlg_fiteval_hydrograph.show()
                self.dlg_fiteval_hydrograph.raise_()
            elif type_calibration == "sedimentograph":
                self.dlg_fiteval_sedimentograph.show()
                self.dlg_fiteval_sedimentograph.raise_()
            
    def calibration_hydrograph_bootstraping_update(self,type_calibration):
        """Method to update graph of bootstraping fo hydrograph"""
        #Update values in lineEdits
        self.update_values_bootstrapping_hydrograph(type_calibration)
        
        #Add the graph
        if type_calibration == "hydrograph":
            canvas = "canvas_calibration_bootstrap_hydrograph"
            dialog = self.dlg_fiteval_hydrograph
        elif type_calibration == "sedimentograph":
            canvas = "canvas_calibration_bootstrap_sedimentograph"
            dialog = self.dlg_fiteval_sedimentograph
            
        if not hasattr(self, canvas):
            #Create the canvas of the graph
            # Si no existe, crear el canvas y añadirlo al layout
            setattr(self,canvas,FigureCanvas(plt.Figure(figsize=(15, 6))))
            # Asignar un layout al QFrame si no tiene uno
            layout = QVBoxLayout(dialog.frame)
            dialog.frame.setLayout(layout)
            #Add canvas to layout
            layout.addWidget(getattr(self,canvas))
        
        #Add graph
        getattr(self,canvas).figure.clear()
        ax1 = getattr(self,canvas).figure.subplots()

        # Histograma
        if type_calibration == "hydrograph":
            finite_nse = [nse for nse in self.nashes_bootstraping_hydrograph if nse != -np.inf]
            inf_count = len([nse for nse in self.nashes_bootstraping_hydrograph if nse == -np.inf])
        elif type_calibration == "sedimentograph":
            finite_nse = [nse for nse in self.nashes_bootstraping_sedimentograph if nse != -np.inf]
            inf_count = len([nse for nse in self.nashes_bootstraping_sedimentograph if nse == -np.inf])
        
        counts, bins, patches = ax1.hist(
            finite_nse, bins=20, density=True, alpha=0.7, color="lightcoral", edgecolor="black", label="Histogram"
        )

        # Función acumulada
        if type_calibration == "hydrograph":
            nashes = np.sort([x for x in self.nashes_bootstraping_hydrograph if not np.isnan(x)])
        elif type_calibration == "sedimentograph":
            nashes = np.sort([x for x in self.nashes_bootstraping_sedimentograph if not np.isnan(x)])
        
        cumulative = [np.searchsorted(nashes, b, side='right') / len(nashes) for b in bins]
        ax2 = ax1.twinx()
        ax2.plot(bins, cumulative, color="teal", lw=2, label="Cumulative")
        
        
        if inf_count>0:
            ax2.set_title(f"-Inf cases: {inf_count}")
        
        #Vertical line
        try:
            ax1.axvline(x=float(dialog.nash.text()), color='red', linestyle='--', linewidth=1.5)
            ax2.hlines(y=float(dialog.p_value.text().split(":")[-1]), xmin=float(dialog.nash.text()), xmax=ax2.get_xlim()[1],transform=ax2.get_yaxis_transform(),color='red', linestyle='--', linewidth=1.5)
        except:
            pass

        # Etiquetas de los ejes
        ax1.set_xlabel("Nash–Sutcliffe Efficiency")
        ax1.set_ylabel("Density")
        ax2.set_ylabel("Cumulative Probability")


        # Personalización de los grids
        ax1.grid(visible=True, linestyle="--", linewidth=0.6, alpha=0.5)
        ax2.grid(visible=False)

        # Leyendas
        lines1, labels1 = ax1.get_legend_handles_labels()
        lines2, labels2 = ax2.get_legend_handles_labels()
        legend = ax1.legend(lines1 + lines2, labels1 + labels2, loc="best")
        
        #Change background color
        getattr(self,canvas).figure.set_facecolor('#f0f0f0')
        ax1.set_facecolor('#f0f0f0')
        # Ajustar los márgenes para añadir más espacio por debajo y por la izquierda
        getattr(self,canvas).figure.subplots_adjust(left=0.2, bottom=0.2,right = 0.8)
        #Draw canvas
        getattr(self,canvas).draw()
        
        #Save figure
        if type_calibration == "hydrograph":
            self.dlg_fiteval_hydrograph.print_graph.clicked.connect(lambda _, b= [self.dlg_fiteval_hydrograph,getattr(self,canvas)]:self.figure_settings(b))
        elif type_calibration == "sedimentograph": 
            self.dlg_fiteval_sedimentograph.print_graph.clicked.connect(lambda _, b= [self.dlg_fiteval_sedimentograph,getattr(self,canvas)]:self.figure_settings(b))
        
            
    
    def update_values_bootstrapping_hydrograph(self,type_calibration):
        """Method to update values in th evaluation of hydrograph calibration"""
        try:
            if type_calibration == "hydrograph":
                dialog = self.dlg_fiteval_hydrograph
            elif type_calibration == "sedimentograph":
                dialog = self.dlg_fiteval_sedimentograph
                
            #Obtain values
            if type_calibration == "hydrograph":
                values = [x for x in self.nashes_bootstraping_hydrograph if not np.isnan(x)]
                values_rmse = [x for x in self.rmse_bootstraping_hydrograph if not np.isnan(x)]
            elif type_calibration == "sedimentograph":
                values = [x for x in self.nashes_bootstraping_sedimentograph if not np.isnan(x)]
                values_rmse = [x for x in self.rmse_bootstraping_sedimentograph if not np.isnan(x)]
            
            #Put p value
            p_value = sum(1 for nash in values if nash < float(dialog.nash.text())) / len(values)
            dialog.p_value.setText(f"p-value: {str(round(p_value,2))}")
            #Put confidence interval for nash
            median = str(round(stats.scoreatpercentile(values,50),2))
            percentile_25 = str(round(stats.scoreatpercentile(values,2.5),2))
            percentile_975 = str(round(stats.scoreatpercentile(values,97.5),2))
            
            dialog.label_3.setText(f"NSE [95%CI]: {median}[{percentile_25} - {percentile_975}]")

            #Same for RMSE
            median = f"{stats.scoreatpercentile(values_rmse,50):.2e}"
            percentile_25 = f"{stats.scoreatpercentile(values_rmse,2.5):.2e}"
            percentile_975 = f"{stats.scoreatpercentile(values_rmse,97.5):.2e}"
            
            dialog.label_7.setText(f"RMSE [95%CI]: {median}[{percentile_25} - {percentile_975}]")
            
            
        except:
            pass
        
    
    def add_pesticides_dialog_sensitivity_design(self):
        """Method to add pesticides to the dialog of sensitivity analysis for design"""
        #Delete previous elements
        num_rows= self.dlg_base.gridLayout_53.rowCount()
        if num_rows>6:
            for i in range(6,num_rows):
                try:
                    widget = self.dlg_base.gridLayout_53.itemAtPosition(i, 0).widget()
                    widget.deleteLater()
                    widget = self.dlg_base.gridLayout_53.itemAtPosition(i, 1).widget()
                    widget.deleteLater()
                except:
                    pass
        
        #Add pesticides
        prj_path = self.obtain_direction_vfsmod(self.dlg_base.vfs_file_sensitivity_design.text())
        if os.path.exists(prj_path) and os.path.isfile(prj_path):
        
            #Obtain number of pesticides
            number_pesticides = self.obtain_number_pestidides(prj_path)
            if number_pesticides is not None:
                self.sensitivity_design_pesticides_present = []
                for i in range(number_pesticides):
                    pesticide = i+1
                    checkbox = QCheckBox(f"Pesticide {pesticide}")
                    setattr(self.dlg_base, f"sensitivity_design_pesticide_check_{pesticide}", checkbox)
                    self.dlg_base.gridLayout_53.addWidget(checkbox, pesticide+5, 0)
                    #Connect to function
                    getattr(self.dlg_base, f"sensitivity_design_pesticide_check_{pesticide}").stateChanged.connect(self.enable_disable_delivery_ratio_lines)
                    

                    # Crear un QLineEdit
                    line_edit = QLineEdit()
                    setattr(self.dlg_base, f"sensitivity_design_pesticide_line_{pesticide}", line_edit)
                    getattr(self.dlg_base, f"sensitivity_design_pesticide_line_{pesticide}").setAlignment(Qt.AlignCenter)
                    self.dlg_base.gridLayout_53.addWidget(line_edit, pesticide+5, 1)
                    
                    #Disable
                    getattr(self.dlg_base, f"sensitivity_design_pesticide_line_{pesticide}").setEnabled(False)
                    getattr(self.dlg_base, f"sensitivity_design_pesticide_line_{pesticide}").setStyleSheet("background-color: #d9d9d9;")
                    
                    #Save the results
                    self.sensitivity_design_pesticides_present.append(pesticide) 
                
    
    def enable_disable_delivery_ratio_lines(self):
        """Method to enable or disable the lines where the user puts the delivery ratios"""
        #Runoff
        if self.dlg_base.sensitivity_design_runoff_check.isChecked():
            self.dlg_base.sensitivity_design_runoff_line.setEnabled(True)
            self.dlg_base.sensitivity_design_runoff_line.setStyleSheet("background-color: #f0f0f0;")
        else:
            self.dlg_base.sensitivity_design_runoff_line.setEnabled(False)
            self.dlg_base.sensitivity_design_runoff_line.setStyleSheet("background-color: #d9d9d9;")
        
        #Sediment
        if self.dlg_base.sensitivity_design_sediment_check.isChecked():
            self.dlg_base.sensitivity_design_sediment_line.setEnabled(True)
            self.dlg_base.sensitivity_design_sediment_line.setStyleSheet("background-color: #f0f0f0;")
        else:
            self.dlg_base.sensitivity_design_sediment_line.setEnabled(False)
            self.dlg_base.sensitivity_design_sediment_line.setStyleSheet("background-color: #d9d9d9;")
            
        #Pesticide
        for pesticide in self.sensitivity_design_pesticides_present:
            if getattr(self.dlg_base, f"sensitivity_design_pesticide_check_{pesticide}").isChecked():
                getattr(self.dlg_base, f"sensitivity_design_pesticide_line_{pesticide}").setEnabled(True)
                getattr(self.dlg_base, f"sensitivity_design_pesticide_line_{pesticide}").setStyleSheet("background-color: #f0f0f0;")
            else:
                getattr(self.dlg_base, f"sensitivity_design_pesticide_line_{pesticide}").setEnabled(False)
