    def direct_input_calibration_pesticide(self):
        """Method to put in the calibration dialog the parameters of the direct input"""
        prj_path = self.obtain_direction_vfsmod(self.dlg_base.single_values_line.text())
        if os.path.exists(prj_path) and os.path.isfile(prj_path):
            #First set invisible all the parameters that are not present in all the situations
            #Function to set visible or invisible horizontal layouts and put "No" in calibration
            def set_visible_horizontal(horizontal,condition):
                for i in range(horizontal.count()):
                    widget = horizontal.itemAt(i).widget()
                    if widget is not None:
                        widget.setVisible(condition)
            #Linear sorption coefficient \n(L/Kg)
            self.dlg_pesticide_calibration.frame_45.setVisible(False)
            set_visible_horizontal(self.dlg_pesticide_calibration.horizontalLayout_108,False)
            self.dlg_pesticide_calibration.no_linear.setChecked(True)
            #Adsorption coefficient \n(L/Kg)
            self.dlg_pesticide_calibration.frame_47.setVisible(False)
            set_visible_horizontal(self.dlg_pesticide_calibration.horizontalLayout_106,False)
            self.dlg_pesticide_calibration.no_adsorption.setChecked(True)
            #Organic carbon\n(%)
            self.dlg_pesticide_calibration.frame_43.setVisible(False)
            set_visible_horizontal(self.dlg_pesticide_calibration.horizontalLayout_110,False)
            self.dlg_pesticide_calibration.no_organic.setChecked(True)
            
            #Obtain iso path
            with open(prj_path, "r") as archivo:
                lineas = archivo.readlines()
            water_quality = False
            for i in lineas:
                if i[:3]=="iwq":
                    iwq_path = i.split("=")[-1]
                    water_quality = True
            if water_quality:
                if not os.path.isabs(iwq_path): #relative path
                    iwq_path = os.path.join(os.path.dirname(prj_path), iwq_path)
                iwq_path = iwq_path.rstrip() #take out the line jumps
                #Read inputs
                if os.path.exists(iwq_path) and os.path.isfile(iwq_path):
                    with open(iwq_path, "r") as archivo:
                        lineas = archivo.readlines()
                    #Obtain value of IKD
                    IKD = int(lineas[1].split()[0])
                    #Put and quit parameters depending on input file
                    if IKD == 0:
                        #Linear sorption coefficient (VKD)
                        self.dlg_pesticide_calibration.frame_45.setVisible(True)
                        set_visible_horizontal(self.dlg_pesticide_calibration.horizontalLayout_108,True)
                    elif IKD == 1:
                        #Adsorption coefficient \n(L/Kg) (KOC)
                        self.dlg_pesticide_calibration.frame_47.setVisible(True)
                        set_visible_horizontal(self.dlg_pesticide_calibration.horizontalLayout_106,True)
                        #Organic carbon\n(%) (OCP) 
                        self.dlg_pesticide_calibration.frame_43.setVisible(True)
                        set_visible_horizontal(self.dlg_pesticide_calibration.horizontalLayout_110,True)
    
    
    def update_buffer_length_table(self):
        """Method to update the buffer segment table when buffer length is changed"""
        try:
            #We obtain information of ikw file
            ikw = self.obtain_direction_prj(self.dlg_base.line_overland.text())
            if os.path.exists(ikw):
                with open(ikw, "r") as archivo:
                    lineas = archivo.readlines()
                
                number_segments = int(lineas[3])
                df = pd.DataFrame(data = {"Distance":[list(map(float, lineas[x].split()))[0] for x in range(4,4+number_segments)],
                                     "Manning":[list(map(float, lineas[x].split()))[1] for x in range(4,4+number_segments)],
                                     "Slope":[list(map(float, lineas[x].split()))[2] for x in range(4,4+number_segments)]})
            else:
                df = self.original_buffer_segments
                
            actual_length = max(df["Distance"])
            length_to_change = float(self.dlg_overland_flow.length.text())
            if length_to_change <= actual_length:
                if length_to_change<min(df["Distance"]): #when distance is smaller than the first interval
                    df = df.head(1)
                else:
                    df = df[df["Distance"]<=length_to_change]
                    df.loc[df.index[-1], "Distance"] = length_to_change
            else:
                df.loc[df.index[-1], "Distance"] = length_to_change
            
            #Add the information to the table
            self.dlg_buffer_segment.tableWidget.itemChanged.disconnect(self.update_buffer_segment_graph) #disconnect. if not each time there is a row update it will be connected
            self.dlg_buffer_segment.tableWidget.setRowCount(0)
            self.dlg_buffer_segment.tableWidget.setRowCount(len(df))
            for fila in range(len(df)):
                for columna in range(len(df.columns)):
                    item = QTableWidgetItem(str(df.iloc[fila,columna]))
                    self.dlg_buffer_segment.tableWidget.setItem(fila, columna, item)
                    item.setTextAlignment(Qt.AlignCenter)
            
            #Connect again
            self.dlg_buffer_segment.tableWidget.itemChanged.connect(self.update_buffer_segment_graph)
            #Update graph
            if hasattr(self, 'ax_buffer_segment'):
                self.update_buffer_segment_graph()
        except:
            pass
    
    def set_working_directory(self):
        """Method to set the directory of the project"""
        #Change the path of projects. If the file is in the working directory then relative path. If not absolute path
        def path_function(lineEdit):
            try:
                if not os.path.isabs(lineEdit.text()): #relative path
                    ruta =  os.path.normpath(os.path.join(self.working_directory, lineEdit.text()))
                else: #absolute path
                    ruta =  os.path.normpath(lineEdit.text())
                new_working_directory = os.path.normpath(self.dlg_base.working_directory_vfsmod.text())
                if os.path.commonpath([ruta, os.path.normpath(new_working_directory)]) == os.path.normpath(new_working_directory):
                    text = os.path.relpath(ruta, new_working_directory)
                else: #absolute path
                    text = ruta
                lineEdit.setText(text)
            except:
                pass
            
        path_function(self.dlg_base.uh_file)
        
        
        path_function(self.dlg_base.line_project_vfsmod)
        path_function(self.dlg_base.design_uh_file)
        path_function(self.dlg_base.design_vfs_file)
        path_function(self.dlg_base.uh_file_sensitivity_design)
        path_function(self.dlg_base.vfs_file_sensitivity_design)
        path_function(self.dlg_base.vfs_project)
        path_function(self.dlg_base.vfs_file)
        path_function(self.dlg_base.single_values_line)
        path_function(self.dlg_base.uh_file_sensitivity)
        path_function(self.dlg_base.vfs_file_sensitivity)
        path_function(self.dlg_base.uh_file_uncertainity)
        path_function(self.dlg_base.vfs_file_uncertainity)
        
        #Add pesticides to combobox
        self.add_pesticides_dialog_sensitivity_inputs("design_uncertainity")
        self.add_pesticides_dialog_sensitivity_inputs("identifiability")
        self.add_pesticides_dialog_sensitivity_inputs("sensitivity_analysis")
        self.add_pesticides_dialog_sensitivity_inputs("uncertainty")
        
        #Change working directory
        self.working_directory = os.path.normpath(self.dlg_base.working_directory_vfsmod.text())
        
    def change_rows_water_quality(self):
        """Method to add/delete rows from the water quality dialog"""
        try:
            num_rows = int(self.dlg_water_quality.days.text())
            current_row_count = self.dlg_water_quality.tableWidget.rowCount()  # Número de filas actuales
            self.dlg_water_quality.tableWidget.setRowCount(num_rows)  # Establecer el número total de filas

            # Para las filas nuevas
            for row in range(current_row_count, num_rows):
                # Primera columna no editable
                item = QTableWidgetItem(str(row+1))
                self.dlg_water_quality.tableWidget.setItem(row, 0, item)
                item.setFlags(item.flags() & ~Qt.ItemIsEditable)  # Primera columna no editable
                item.setTextAlignment(Qt.AlignCenter)

                # Segunda y tercera columna editable y centrado
                for col in range(1, 3):  # Para las columnas 1 y 2 (segunda y tercera)
                    item = QTableWidgetItem("")
                    self.dlg_water_quality.tableWidget.setItem(row, col, item)
                    item.setTextAlignment(Qt.AlignCenter)

        except:
            pass
        
    def hide_mass_balance_frame(self):
        """Method to show/hide frame for mass balance calculation in water quality"""
        #Hide elements
        if self.dlg_water_quality.calculation.currentIndex() == 0:
            #Degradation data
            self.dlg_water_quality.frame_8.hide()
            #Days degradation
            self.dlg_water_quality.tableWidget.hide()
            #Top soil field capacity
            self.dlg_water_quality.field_capacity.setEnabled(False)
            self.dlg_water_quality.field_capacity.setStyleSheet("background-color: #d9d9d9;")
            #Days between runnof events
            self.dlg_water_quality.days.setEnabled(False)
            self.dlg_water_quality.days.setStyleSheet("background-color: #d9d9d9;")
            
            #Pesticide half life and dispersion length of chemical  
            for pesticide in range(1,self.maximum_number_pesticides_dialog+1):
                #Half life
                getattr(self.dlg_water_quality, f"half_life_{pesticide}").setEnabled(False)
                getattr(self.dlg_water_quality, f"half_life_{pesticide}").setStyleSheet("background-color: #d9d9d9;")
                #Dispersion length of chemical
                getattr(self.dlg_water_quality, f"dispersion_{pesticide}").setEnabled(False)
                getattr(self.dlg_water_quality, f"dispersion_{pesticide}").setStyleSheet("background-color: #d9d9d9;")
                
            
            
        #Show elements
        else: 
            #Degradation data
            self.dlg_water_quality.frame_8.show()
            #Days degradation
            self.dlg_water_quality.tableWidget.show()
            #Top soil field capacity
            self.dlg_water_quality.field_capacity.setEnabled(True)
            self.dlg_water_quality.field_capacity.setStyleSheet("background-color: #f0f0f0 ;")
            #Days between runnof events
            self.dlg_water_quality.days.setEnabled(True)
            self.dlg_water_quality.days.setStyleSheet("background-color: #f0f0f0 ;")
            
            #Pesticide half life and dispersion length of chemical  
            for pesticide in range(1,self.maximum_number_pesticides_dialog+1):
                #Half life
                getattr(self.dlg_water_quality, f"half_life_{pesticide}").setEnabled(True)
                getattr(self.dlg_water_quality, f"half_life_{pesticide}").setStyleSheet("background-color: #f0f0f0;")
                #Dispersion length of chemical
                getattr(self.dlg_water_quality, f"dispersion_{pesticide}").setEnabled(True)
                getattr(self.dlg_water_quality, f"dispersion_{pesticide}").setStyleSheet("background-color: #f0f0f0;")
            
    
    def show_sensitivity_graph_design(self):
        """Method to add the outputs for the graph visualization for design"""
        #I iterate throughout all the paths and select all the outputs
        paths = [self.dlg_base.csv_results_morris_design_uncertainity,self.dlg_base.csv_results_fast_design_uncertainity,
            self.dlg_base.csv_results_sobol_design_uncertainity]
        
        outputs = []
        for path in paths:
            path =self.obtain_direction_vfsmod(path.text()) 
            if os.path.exists(path) and os.path.isfile(path):
                with open(path, mode='r', encoding='utf-8') as file:
                    lines = file.read().splitlines()
                #Obtain output names
                for i in range(len(lines)):
                    if lines[i] == "----------------------------------------------------------------------":
                        if len(lines[i+1].split(","))>1:
                            break
                        else:
                            outputs.append(lines[i+1])
        #Obtain unique values and order them alphabetically
        outputs = list(set(outputs))
        outputs.sort()
            
        #Obtain the name of the output that was selected previously if there was something
        output_previously = False
        if self.dlg_base.frame_39.layout() != None:
            for i in range(self.dlg_base.frame_39.layout().count()):
                item = self.dlg_base.frame_39.layout().itemAt(i)
                widget = item.widget()
                
                #Checks if the widget is a QCheckBox and if it is selected and it is a present output.
                if isinstance(widget, QRadioButton) and widget.isChecked() and widget.text() in outputs:
                    output_previously = True
                    output = widget.text()
        
        #Add the outputs
        if len(outputs)>0:
            if self.dlg_base.frame_39.layout() is not None:
                layout_frame_22 = self.dlg_base.frame_39.layout()
            else:
                layout_frame_22 = QVBoxLayout()
                self.dlg_base.frame_39.setLayout(layout_frame_22)

            # Elimina todos los QRadioButton existentes y cualquier espaciador
            for i in reversed(range(layout_frame_22.count())):
                item = layout_frame_22.itemAt(i)
                widget = item.widget()
                
                # Elimina el widget si es un QRadioButton or label
                if isinstance(widget, QRadioButton) or isinstance(widget, QLabel):
                    widget.deleteLater()
                elif item.spacerItem() is not None:
                    layout_frame_22.removeItem(item)
            #Add label
            label = QLabel("Outputs")
            layout_frame_22.addWidget(label)
            
            # Crear y añadir nuevos QRadioButtons
            outputs_checks = []
            for opcion in outputs:
                radio_button = QRadioButton(opcion)
                # Conectar la función solo una vez
                radio_button.toggled.connect(lambda checked, rb=radio_button: self.udpate_buffer_length_cumulative() if checked else None)
                layout_frame_22.addWidget(radio_button)
                outputs_checks.append([opcion,radio_button])

            # Añade el espaciador de nuevo después de los nuevos QRadioButtons
            spacer = QSpacerItem(20, 40, QSizePolicy.Minimum, QSizePolicy.Expanding)
            layout_frame_22.addItem(spacer)
            #Select one radiobutton
            if output_previously:
                for i in outputs_checks:
                    if i[0]==output:
                        i[1].setChecked(True)
            else:
                outputs_checks[0][1].setChecked(True)
                
    
    
