    def show_owq_graph_reduction(self):
        """Method to show the dialog with water quality balance graph"""
        #Delete radio buttons of pesticides
        if self.dlg_owq_graph_reduction.frame_3.layout() is not None:
            # Obtén el layout actual
            layout = self.dlg_owq_graph_reduction.frame_3.layout()
            
            # Elimina todos los widgets y elementos del layout (incluyendo espaciadores)
            while layout.count():
                item = layout.takeAt(0)
                widget = item.widget()
                if widget is not None:
                    widget.deleteLater()  # Elimina el widget
                elif item.spacerItem() is not None:
                    layout.removeItem(item)  # Elimina el espaciador

        else:
            # Si no hay un layout, crea uno nuevo
            layout = QVBoxLayout()
            self.dlg_owq_graph_reduction.frame_3.setLayout(layout)
            
           
        #Obtain results
        ruta = self.obtain_direction_prj(self.dlg_base.line_quality.text())
        if os.path.exists(ruta):
            #Obtain values
            with open(ruta, "r") as archivo:
                lineas_owq = archivo.readlines()
            
            #Add number of pesticides
            for i in range(len(lineas_owq)):
                if lineas_owq[i][:44] == "Parameters for Water Quality - No. Compounds":
                        pesticide = int(lineas_owq[i].split("=")[-1])
            #Add pesticides
            # Agrega el QLabel
            label = QLabel("Select pesticide")
            layout.addWidget(label)

            # Lista de nombres para los QRadioButtons
            pesticides = [f"Pesticide {x+1}" for x in range(pesticide)]
            self.dictionary_radio_inputs_pesticides = {}

            # Crear y añadir varios QRadioButton
            for opcion in pesticides:
                radio_button = QRadioButton(opcion)
                # Conectar la función solo una vez
                radio_button.toggled.connect(lambda checked, rb=radio_button: self.update_owq_graph_reduction(rb.text()) if checked else None)
                self.dictionary_radio_inputs_pesticides[radio_button] = opcion
                layout.addWidget(radio_button)

            # Añade un espaciador para ajustar la posición
            spacer = QSpacerItem(20, 40, QSizePolicy.Minimum, QSizePolicy.Expanding)
            layout.addItem(spacer)

            # Selecciona el primer QRadioButton
            if self.dictionary_radio_inputs_pesticides:
                list(self.dictionary_radio_inputs_pesticides.keys())[0].setChecked(True)
            
            #Show dialog
            self.dlg_owq_graph_reduction.show()
            self.dlg_owq_graph_reduction.raise_()
    
    
    
    def update_owq_graph_reduction(self,pesticide):
        """Method to update graph balance of pesticide data"""
        #Obtain data
        number_pesticide = int(pesticide.split()[-1])
        
        ruta = self.obtain_direction_prj(self.dlg_base.line_quality.text())
        #Obtain values
        with open(ruta, "r") as archivo:
            lineas_owq = archivo.readlines()
                
        #Function to obtain infomation of owq file
        def obtain_result_owq(string,number_pesticide):
            condition_one = False
            contador = 0
            for i in lineas_owq:
                if i.lstrip() == "Outputs for Water Quality\n":
                    condition_one = True
                if condition_one and i.split("=")[-1] == " Runoff inflow\n":
                    contador +=1
                if i.split("=")[-1]==string and contador == int(number_pesticide):
                    for k in i.split("=")[0].split(" "):
                        try:
                            output = float(k)
                            return output
                        except:
                            pass

        #Obtain inputs
        infiltration = obtain_result_owq(" Infiltration (dQ)\n",number_pesticide)
        sediment = obtain_result_owq(" Sediment reduction (dE)\n",number_pesticide)
        runoff = obtain_result_owq(" Runoff inflow reduction\n",number_pesticide)
        pesticide = obtain_result_owq(" Pesticide reduction (dP)\n",number_pesticide)
        
        
        #Create graph
        #Add layout
        #If canvas exist then clear. If not then create it. 
        if not hasattr(self, 'canvas_owq_graph_reduction'):
            # Si no existe, crear el canvas y añadirlo al layout
            self.canvas_owq_graph_reduction = FigureCanvas(plt.Figure(figsize=(15, 6)))
            
            # Asignar un layout al QFrame si no tiene uno
            layout = QVBoxLayout(self.dlg_owq_graph_reduction.frame)
            self.dlg_owq_graph_reduction.frame.setLayout(layout)
            
            # Añadir el canvas al layout
            layout.addWidget(self.canvas_owq_graph_reduction)
            
        else:
            # Si ya existe, simplemente limpiar el canvas
            self.canvas_owq_graph_reduction.figure.clear()
    
        self.ax_owq_graph_reduction= self.canvas_owq_graph_reduction.figure.subplots()
    
        # Clear canvas
        self.ax_owq_graph_reduction.clear()
        
        #Create graph
        names = ['Infiltration (dQ)', 'Sediment (dE)', 'Runoff inflow',"Pesticide (dP)"]
        valores = [infiltration, sediment, runoff,pesticide]
        

        # Crear el gráfico de barras
        bars = self.ax_owq_graph_reduction.bar(names, valores,color ="red")
        
        #Add values to the top of the bars
        for bar in bars:
            yval = bar.get_height()
            self.ax_owq_graph_reduction.text(bar.get_x() + bar.get_width()/2, yval, round(yval, 2),
                                       ha='center', va='bottom', fontsize=9, color='black',weight ="bold")

        
        #Axis
        self.ax_owq_graph_reduction.set_ylabel("Reduction (%)",size = 10,family="arial",weight = "bold",color = "black")

        
        #Change y limit
        self.ax_owq_graph_reduction.set_ylim(0, max(valores)*1.1)

        #Thousand separator
        def xfunc(x,pos):
            s = '{:0,d}'.format(int(x))
            return s
        x_format = tkr.FuncFormatter(xfunc)
        self.ax_owq_graph_reduction.yaxis.set_major_formatter(x_format)
        
        #Change background color
        self.canvas_owq_graph_reduction.figure.set_facecolor('#f0f0f0')
        self.ax_owq_graph_reduction.set_facecolor('#f0f0f0')

        # Ajustar los márgenes para añadir más espacio por debajo y por la izquierda
        self.canvas_owq_graph_reduction.figure.subplots_adjust(left=0.1, bottom=0.1)
        
        # Redraw the canvas
        self.canvas_owq_graph_reduction.draw()
        
        #Save figure
        self.dlg_owq_graph_reduction.print_graph.clicked.connect(lambda _, b= [self.dlg_owq_graph_reduction,self.canvas_owq_graph_reduction]:self.figure_settings(b))
    
    
    def show_owq_graph_evolution(self):
        """Method to show the dialog with water quality balance graph"""
        #Obtain results
        ruta = self.obtain_direction_prj(self.dlg_base.line_quality.text())
        if os.path.exists(ruta):
            #Obtain values
            with open(ruta, "r") as archivo:
                lineas_owq = archivo.readlines()
                show_graph = False
                for l in range(len(lineas_owq)):
                        if lineas_owq[l].lstrip() == "Compound degradation between runoff events (mg)\n":
                            show_graph = True
                            column_raw = lineas_owq[l+2].split()
                            columns = ["Time(d)"]
                            for c in column_raw:
                                try:
                                    int(c)
                                    columns.append(f"Pesticide {c}")
                                except:
                                    pass
                            rows = []
                            for row in range(l+3,len(lineas_owq)):
                                if  len(lineas_owq[row].split())== 0:
                                    break
                                values = [float(x) for x in lineas_owq[row].split()]
                                rows.append(values)
                            data = pd.DataFrame(rows, columns=columns)
                            break
                
            if show_graph:
                #Add layout
                #If canvas exist then clear. If not then create it. 
                if not hasattr(self, 'canvas_owq_graph_evolution'):
                    # Si no existe, crear el canvas y añadirlo al layout
                    self.canvas_owq_graph_evolution = FigureCanvas(plt.Figure(figsize=(15, 6)))
                    
                    # Asignar un layout al QFrame si no tiene uno
                    layout = QVBoxLayout(self.dlg_owq_graph_evolution.frame)
                    self.dlg_owq_graph_evolution.frame.setLayout(layout)
                    
                    # Añadir el canvas al layout
                    layout.addWidget(self.canvas_owq_graph_evolution)
                    
                else:
                    # Si ya existe, simplemente limpiar el canvas
                    self.canvas_owq_graph_evolution.figure.clear()
            
                self.ax_owq_graph_reduction= self.canvas_owq_graph_evolution.figure.subplots()
            
                # Clear canvas
                self.ax_owq_graph_reduction.clear()
                
                #Create graph
                for col in data.columns:
                    if col != "Time(d)":
                        self.ax_owq_graph_reduction.plot(data["Time(d)"], data[col], marker='o', label=col)
                
                #Axis
                self.ax_owq_graph_reduction.set_xlabel("Time (days)",size = 10,family="arial",weight = "bold",color = "black")
                self.ax_owq_graph_reduction.set_ylabel("Residual mass, $m_{i}$ (mg)",size = 10,family="arial",weight = "bold",color = "black")
                
                #Only integer values in x axis
                self.ax_owq_graph_reduction.xaxis.set_major_locator(MaxNLocator(integer=True))
                
                # Add legend and change color
                legend = self.ax_owq_graph_reduction.legend(
                    loc="lower center",  # Centrar horizontalmente
                    bbox_to_anchor=(0.5, 1.01),  # Posición justo arriba del gráfico
                    ncol=4,  # Número de columnas en la leyenda
                    frameon=False
                )
                
                #Change color legend
                legend.get_frame().set_facecolor("#f0f0f0")

                #Thousand separator
                def xfunc(x,pos):
                    s = '{:0,d}'.format(int(x))
                    return s
                x_format = tkr.FuncFormatter(xfunc)
                self.ax_owq_graph_reduction.yaxis.set_major_formatter(x_format)
                
                #Change background color
                self.canvas_owq_graph_evolution.figure.set_facecolor('#f0f0f0')
                self.ax_owq_graph_reduction.set_facecolor('#f0f0f0')

                # Ajustar los márgenes para añadir más espacio por debajo y por la izquierda
                self.canvas_owq_graph_evolution.figure.subplots_adjust(left=0.2, bottom=0.2)
                
                # Redraw the canvas
                self.canvas_owq_graph_evolution.draw()
                
                #Save figure
                self.dlg_owq_graph_evolution.print_graph.clicked.connect(lambda _, b= [self.dlg_owq_graph_evolution,self.canvas_owq_graph_evolution]:self.figure_settings(b))
                
                
                #Show dialog
                self.dlg_owq_graph_evolution.show()
                self.dlg_owq_graph_evolution.raise_()
    
    
    def show_owq_graph_balance(self):
        """Method to show the dialog with water quality balance graph"""
        #Delete radio buttons of pesticides
        if self.dlg_owq_graph_balance.frame_2.layout() is not None:
            # Obtén el layout actual
            layout = self.dlg_owq_graph_balance.frame_2.layout()
            
            # Elimina todos los widgets y elementos del layout (incluyendo espaciadores)
            while layout.count():
                item = layout.takeAt(0)
                widget = item.widget()
                if widget is not None:
                    widget.deleteLater()  # Elimina el widget
                elif item.spacerItem() is not None:
                    layout.removeItem(item)  # Elimina el espaciador

        else:
            # Si no hay un layout, crea uno nuevo
            layout = QVBoxLayout()
            self.dlg_owq_graph_balance.frame_2.setLayout(layout)
            
           
        #Obtain results
        ruta = self.obtain_direction_prj(self.dlg_base.line_quality.text())
        if os.path.exists(ruta):
            #Obtain values
            with open(ruta, "r") as archivo:
                lineas_owq = archivo.readlines()
            
            #Add number of pesticides
            for i in range(len(lineas_owq)):
                if lineas_owq[i][:44] == "Parameters for Water Quality - No. Compounds":
                        pesticide = int(lineas_owq[i].split("=")[-1])
            #Add pesticides
            # Agrega el QLabel
            label = QLabel("Select pesticide")
            layout.addWidget(label)

            # Lista de nombres para los QRadioButtons
            pesticides = [f"Pesticide {x+1}" for x in range(pesticide)]
            self.dictionary_radio_inputs_pesticides = {}

            # Crear y añadir varios QRadioButton
            for opcion in pesticides:
                radio_button = QRadioButton(opcion)
                # Conectar la función solo una vez
                radio_button.toggled.connect(lambda checked, rb=radio_button: self.update_owq_graph_balance(rb.text()) if checked else None)
                self.dictionary_radio_inputs_pesticides[radio_button] = opcion
                layout.addWidget(radio_button)

            # Añade un espaciador para ajustar la posición
            spacer = QSpacerItem(20, 40, QSizePolicy.Minimum, QSizePolicy.Expanding)
            layout.addItem(spacer)

            # Selecciona el primer QRadioButton
            if self.dictionary_radio_inputs_pesticides:
                list(self.dictionary_radio_inputs_pesticides.keys())[0].setChecked(True)
            
            #Show dialog
            self.dlg_owq_graph_balance.show()
            self.dlg_owq_graph_balance.raise_()
            
    def update_owq_graph_balance(self,pesticide):
        """Method to update graph balance of pesticide data"""
        try:
            #Obtain data
            number_pesticide = int(pesticide.split()[-1])
            
            ruta = self.obtain_direction_prj(self.dlg_base.line_quality.text())
            #Obtain values
            with open(ruta, "r") as archivo:
                lineas_owq = archivo.readlines()
                    
            #Function to obtain infomation of owq file
            def obtain_result_owq(string,number_pesticide):
                condition = False
                for i in lineas_owq:
                    if i == f" Normalized values by source area:\n":
                        condition = True
                    if i.split("=")[-1].rstrip()==string and condition:
                        if string != " Source Area (input)":
                            return float(i.split("=")[0].split()[int(number_pesticide)-1])
                        else:
                            return float(i.split("=")[0].split()[0])

            def obtain_result_owq_2(string,number_pesticide):
                condition = False
                contador = 0
                for i in lineas_owq:
                    if i == " Huang & van Genuchten (1995) CDE analytical solution\n":
                        contador += 1
                    if contador == int(number_pesticide):
                        condition = True
                    if i.split("=")[0]==string and condition:
                        return float(i.split("=")[1].split()[0])
                        
            def obtain_result_owq_3(string,number_pesticide):
                condition = False
                length_string = len(string)
                for i in lineas_owq:
                    if i == f" Normalized values by source area:\n":
                        condition = True
                    
                    if i.split("=")[-1][:length_string]==string and condition:
                        return float(i.split("=")[0].split()[int(number_pesticide)-1])
                        
                        
            #Obtain inputs
            source_area = obtain_result_owq(" Source Area (input)",number_pesticide)
            pesticide_input = obtain_result_owq(" Pesticide input (mi)",number_pesticide)
            pesticide_output = obtain_result_owq(" Pesticide output (mo)",number_pesticide)
            output_liquid = obtain_result_owq(" Pesticide outflow in liquid phase (mod)",number_pesticide)
            output_solid = obtain_result_owq(" Pesticide outflow in solid phase (mop)",number_pesticide)
            trapped_in_vfs = obtain_result_owq(" Pesticide trapped in VFS (mf)",number_pesticide)
            trapped_in_sediment = obtain_result_owq(" Pesticide trapped with sediment (mfsed)",number_pesticide)
            trapped_in_mixing_layer = obtain_result_owq(" Pesticide trapped in mixing layer (mfml)",number_pesticide)
            sorbed_mixing_layer_last_event = obtain_result_owq(" Pesticide sorbed in mixing layer from last event (mfml0)",number_pesticide)

            soil_profile = obtain_result_owq_2("        Soil profile total mass (mfF mg)",number_pesticide)/source_area
            soil_profile_dissolved = obtain_result_owq_2("   Soil profile dissolved mass (mfFd mg)",number_pesticide)/source_area
            soil_profile_sorbed = obtain_result_owq_2("      Soil profile sorbed mass (mfFp mg)",number_pesticide)/source_area
            mixing_layer_dissolved = obtain_result_owq_2("  Mixing layer dissolved mass (mfmld mg)",number_pesticide)/source_area
            mixing_layer_sorbed = obtain_result_owq_2("     Mixing layer sorbed mass (mfmlp mg)",number_pesticide)/source_area
            
            total_residue_after_degradation = obtain_result_owq_3(" Total surface residue after degradation",number_pesticide)
            dissolved_surface_residue_after_degradation = obtain_result_owq_3(" Dissolved surface residue after degradation",number_pesticide)
            sorbed_surface_residue_after_degradation = obtain_result_owq_3(" Sorbed surface residue after degradation",number_pesticide)
            
            
            #Create graph
            #Add layout
            #If canvas exist then clear. If not then create it. 
            if not hasattr(self, 'canvas_owq_graph_balance'):
                # Si no existe, crear el canvas y añadirlo al layout
                self.canvas_owq_graph_balance = FigureCanvas(plt.Figure(figsize=(15, 6)))
                
                # Asignar un layout al QFrame si no tiene uno
                layout = QVBoxLayout(self.dlg_owq_graph_balance.frame)
                self.dlg_owq_graph_balance.frame.setLayout(layout)
                
                # Añadir el canvas al layout
                layout.addWidget(self.canvas_owq_graph_balance)
                
            else:
                # Si ya existe, simplemente limpiar el canvas
                self.canvas_owq_graph_balance.figure.clear()
        
            self.ax_owq_graph_balance= self.canvas_owq_graph_balance.figure.subplots(1,2)
        
            # Clear canvas
            self.ax_owq_graph_balance[0].clear()
            self.ax_owq_graph_balance[1].clear()
            
            try:
                sizes_today = [output_solid, output_liquid, soil_profile_sorbed-mixing_layer_sorbed, 
                    soil_profile_dissolved-mixing_layer_dissolved,sorbed_mixing_layer_last_event, trapped_in_sediment,mixing_layer_sorbed, mixing_layer_dissolved]  # Proporciones
                
                #Labels with percentage
                labels_today = [
                    f'Outflow sorbed ({round(100*output_solid/sum(sizes_today),2)}%)', f'Outflow dissolved ({round(100*output_liquid/sum(sizes_today),2)}%)',
                    f'Leached sorbed ({round(100*(soil_profile_sorbed-mixing_layer_sorbed)/sum(sizes_today),2)}%)', f'Leached dissolved ({round(100*(soil_profile_dissolved-mixing_layer_dissolved)/sum(sizes_today),2)}%)',
                    f'Sorbed in mixing layer from last event ({round(100*sorbed_mixing_layer_last_event/sum(sizes_today),2)}%)',
                    f'Trapped with sediment ({round(100*trapped_in_sediment/sum(sizes_today),2)}%)',
                    f'Mixing layer sorbed ({round(100*mixing_layer_sorbed/sum(sizes_today),2)}%)', f'Mixing layer dissolved ({round(100*mixing_layer_dissolved/sum(sizes_today),2)}%)'
                    ]
                    
                
                colors = [
                    '#1f77b4',  # Outflow solid (azul claro)
                    '#66b3ff',  # Outflow liquid (azul más claro)
                    '#2ca02c',  # Infiltrated sorbed (verde claro)
                    '#145a32',  # Infiltrated dissolved (verde más oscuro)
                    "#a569bd",  # Sorbed in mixing layer from last event
                    '#e74c3c',   # Trapped with sediment (rojo)
                    '#ff7f0e',  # Mixing layer sorbed (naranja)
                    '#d35400',  # Mixing layer dissolved (naranja más oscuro)
                ]
                
                threshold = sum(sizes_today)*0.05  # Umbral para los valores pequeños

                # Crear el gráfico de pastel
                wedges, texts =self.ax_owq_graph_balance[0].pie(
                    sizes_today,
                    colors=colors,
                    autopct=None,
                    startangle=140,
                    wedgeprops={'edgecolor': 'black'},
                    pctdistance=0.85,  # Para valores absolutos dentro del pie
                    labeldistance=None  # Elimina las etiquetas fuera del pie
                )

                # Recorrer cada segmento del gráfico de pastel
                for i, p in enumerate(self.ax_owq_graph_balance[0].patches):
                    # Cálculo del ángulo central del arco
                    ang = (p.theta2 - p.theta1) / 2. + p.theta1
                    x = 0.6 * np.cos(np.deg2rad(ang))  # Coordenada x dentro del segmento
                    y = 0.6 * np.sin(np.deg2rad(ang))  # Coordenada y dentro del segmento
                    horizontalalignment = {-1: "right", 1: "left"}[int(np.sign(x))]
                    #Only put data if is above threshold
                    if sizes_today[i] > threshold:
                        # Si el valor es mayor o igual al umbral, poner la etiqueta dentro del pie
                        self.ax_owq_graph_balance[0].annotate(
                            f'{round(sizes_today[i], 2)} mg/m\u00b2',
                            xy=(x, y),
                            horizontalalignment='center',  # Centrar dentro del segmento
                            verticalalignment='center',fontsize = 10, fontweight = "bold"
                        )
                
                
                #Legend
                handles = [mpatches.Patch(color=colors[i], label=labels_today[i]) for i in range(len(labels_today))]
                
                handles_first, labels_first = handles[:4], labels_today[:4]
                handles_second, labels_second = handles[4:], labels_today[4:]
                
                self.ax_owq_graph_balance[0].legend_ = None  

                # Crear la primera leyenda (5 elementos)
                legend1 = self.ax_owq_graph_balance[0].legend(
                    handles_first, labels_first,
                    loc='lower center',
                    bbox_to_anchor=(-0.2, -0.37),  # Ajusta posición
                    fontsize='small',
                    ncol=1,  # Una columna para mostrar 5 filas
                    frameon=False,
                    title  = "Residues not to be degraded"
                )

                # Agregar la primera leyenda antes de la segunda
                self.ax_owq_graph_balance[0].add_artist(legend1)

                # Crear la segunda leyenda (2 elementos)
                legend2 = self.ax_owq_graph_balance[0].legend(
                    handles_second, labels_second,
                    loc='lower center',
                    bbox_to_anchor=(0.95, -0.37),  # Ajusta posición más a la derecha
                    fontsize='small',
                    ncol=1,  # Una columna para mostrar 2 filas
                    frameon=False,
                    title = "Residues to be degraded"
                )

                
                
                #Title
                self.ax_owq_graph_balance[0].set_title("Pesticides mass distribution after event")
            
            
            except:
                # Put white pie chart
                self.ax_owq_graph_balance[0].clear()
                self.ax_owq_graph_balance[0].pie(
                    [1],
                    colors=["white"],
                    wedgeprops=dict(edgecolor="black")
                )
                self.ax_owq_graph_balance[0].set_aspect("equal")
                self.ax_owq_graph_balance[0].axis("off")

                # Title
                self.ax_owq_graph_balance[0].set_title("Pesticides mass distribution after event")

                # ----- Añadir leyenda con todos los valores a 0 -----
                labels_today = [
                    'Outflow sorbed (0%)', 
                    'Outflow dissolved (0%)',
                    'Leached sorbed (0%)', 
                    'Leached dissolved (0%)',
                    'Sorbed in mixing layer from last event (0%)',
                    'Trapped with sediment (0%)',
                    'Mixing layer sorbed (0%)', 
                    'Mixing layer dissolved (0%)'
                ]

                colors = [
                    '#1f77b4',  # Outflow solid (azul claro)
                    '#66b3ff',  # Outflow liquid (azul más claro)
                    '#2ca02c',  # Infiltrated sorbed (verde claro)
                    '#145a32',  # Infiltrated dissolved (verde más oscuro)
                    "#a569bd",  # Sorbed in mixing layer from last event
                    '#e74c3c',  # Trapped with sediment (rojo)
                    '#ff7f0e',  # Mixing layer sorbed (naranja)
                    '#d35400',  # Mixing layer dissolved (naranja más oscuro)
                ]

                # Crear handles para la leyenda
                handles = [mpatches.Patch(color=colors[i], label=labels_today[i]) for i in range(len(labels_today))]

                # Dividir las leyendas como en el caso normal
                handles_first, labels_first = handles[:4], labels_today[:4]
                handles_second, labels_second = handles[4:], labels_today[4:]

                # Eliminar leyenda previa si existe
                self.ax_owq_graph_balance[0].legend_ = None  

                # Primera leyenda
                legend1 = self.ax_owq_graph_balance[0].legend(
                    handles_first, labels_first,
                    loc='lower center',
                    bbox_to_anchor=(-0.2, -0.37),
                    fontsize='small',
                    ncol=1,
                    frameon=False,
                    title="Residues not to be degraded"
                )
                self.ax_owq_graph_balance[0].add_artist(legend1)

                # Segunda leyenda
                legend2 = self.ax_owq_graph_balance[0].legend(
                    handles_second, labels_second,
                    loc='lower center',
                    bbox_to_anchor=(0.95, -0.37),
                    fontsize='small',
                    ncol=1,
                    frameon=False,
                    title="Residues to be degraded"
                )
                
            
            
            try:
                sizes_tomorrow = [dissolved_surface_residue_after_degradation, sorbed_surface_residue_after_degradation]  # Proporciones diferentes

                #Labels with percetage
                labels_tomorrow = [
                    f'Dissolved surface residue \nafter degradation ({round(100*dissolved_surface_residue_after_degradation/sum(sizes_tomorrow),2)}%)', 
                    f'Sorbed surface residue \nafter degradation ({round(100*sorbed_surface_residue_after_degradation/sum(sizes_tomorrow),2)}%)'
                ]
                
                #Colors
                colors_tomorrow = [
                    '#c2f0f0',  # Dissolved surface residue
                    '#ffb3b3'   # Sorbed surface residue
                ]
                
                #Create pie
                self.ax_owq_graph_balance[1].pie(
                    sizes_tomorrow,
                    colors=colors_tomorrow,
                    autopct=None,
                    startangle=140,
                    wedgeprops={'edgecolor': 'black'},
                    pctdistance=0.85,  # Para valores absolutos dentro del pie
                    labeldistance=None  # Elimina las etiquetas fuera del pie
                )
                
                threshold = sum(sizes_tomorrow)*0.05  # Umbral para los valores pequeños
                # Recorrer cada segmento del gráfico de pastel
                for i, p in enumerate(self.ax_owq_graph_balance[1].patches):
                    # Cálculo del ángulo central del arco
                    ang = (p.theta2 - p.theta1) / 2. + p.theta1
                    x = 0.5 * np.cos(np.deg2rad(ang))  # Coordenada x dentro del segmento
                    y = 0.5 * np.sin(np.deg2rad(ang))  # Coordenada y dentro del segmento
                    horizontalalignment = {-1: "right", 1: "left"}[int(np.sign(x))]

                    #Only put data if is above threshold
                    if sizes_tomorrow[i] > threshold:
                        # Si el valor es mayor o igual al umbral, poner la etiqueta dentro del pie
                        self.ax_owq_graph_balance[1].annotate(
                            f'{round(sizes_tomorrow[i], 2)} mg/m\u00b2',
                            xy=(x, y),
                            horizontalalignment='center',  # Centrar dentro del segmento
                            verticalalignment='center',fontsize = 10, fontweight = "bold"
                        )

                #Legend
                handles_tomorrow = [mpatches.Patch(color=colors_tomorrow[i], label=labels_tomorrow[i], edgecolor="none") for i in range(len(labels_tomorrow))]
                
                self.ax_owq_graph_balance[1].legend(
                     handles_tomorrow,labels_tomorrow,
                    loc='lower center',
                    bbox_to_anchor=(0.6, -0.32),
                    fontsize='small',
                    ncol=1,  # Dos columnas en la leyenda
                    frameon=False,  # Fondo transparente y sin borde
                    title = "Degraded residues"
                )
                
                #Título
                self.ax_owq_graph_balance[1].set_title("Pesticides mass distribution after degradation")
            except:
                # Put white pie chart
                self.ax_owq_graph_balance[1].clear()
                self.ax_owq_graph_balance[1].pie(
                    [1],
                    colors=["white"],
                    wedgeprops=dict(edgecolor="black")
                )
                self.ax_owq_graph_balance[1].set_aspect("equal")
                self.ax_owq_graph_balance[1].axis("off")

                # Title
                self.ax_owq_graph_balance[1].set_title("Pesticides mass distribution after event")

                # ----- Añadir leyenda con todos los valores a 0 -----
                labels_today = [
                    'Outflow sorbed (0%)', 
                    'Outflow dissolved (0%)',
                    'Leached sorbed (0%)', 
                    'Leached dissolved (0%)',
                    'Sorbed in mixing layer from last event (0%)',
                    'Trapped with sediment (0%)',
                    'Mixing layer sorbed (0%)', 
                    'Mixing layer dissolved (0%)'
                ]

                colors = [
                    '#1f77b4',  # Outflow solid (azul claro)
                    '#66b3ff',  # Outflow liquid (azul más claro)
                    '#2ca02c',  # Infiltrated sorbed (verde claro)
                    '#145a32',  # Infiltrated dissolved (verde más oscuro)
                    "#a569bd",  # Sorbed in mixing layer from last event
                    '#e74c3c',  # Trapped with sediment (rojo)
                    '#ff7f0e',  # Mixing layer sorbed (naranja)
                    '#d35400',  # Mixing layer dissolved (naranja más oscuro)
                ]

                # Crear handles para la leyenda
                handles = [mpatches.Patch(color=colors[i], label=labels_today[i]) for i in range(len(labels_today))]

                # Dividir las leyendas como en el caso normal
                handles_first, labels_first = handles[:4], labels_today[:4]
                handles_second, labels_second = handles[4:], labels_today[4:]

                # Eliminar leyenda previa si existe
                self.ax_owq_graph_balance[1].legend_ = None  

                # Primera leyenda
                legend1 = self.ax_owq_graph_balance[1].legend(
                    handles_first, labels_first,
                    loc='lower center',
                    bbox_to_anchor=(-0.2, -0.37),
                    fontsize='small',
                    ncol=1,
                    frameon=False,
                    title="Residues not to be degraded"
                )
                self.ax_owq_graph_balance[1].add_artist(legend1)

                # Segunda leyenda
                legend2 = self.ax_owq_graph_balance[1].legend(
                    handles_second, labels_second,
                    loc='lower center',
                    bbox_to_anchor=(0.95, -0.37),
                    fontsize='small',
                    ncol=1,
                    frameon=False,
                    title="Residues to be degraded"
                )
                
            
            

            # Ajustar los márgenes para añadir más espacio por debajo y por la izquierda
            self.canvas_owq_graph_balance.figure.subplots_adjust(left=0.2, bottom=0.2)
            #Change background color
            self.canvas_owq_graph_balance.figure.set_facecolor('#f0f0f0')
            self.ax_owq_graph_balance[0].set_facecolor('#f0f0f0')
            self.ax_owq_graph_balance[1].set_facecolor('#f0f0f0')
            #Adjust distance between piecharts
            self.canvas_owq_graph_balance.figure.subplots_adjust(wspace=0.5)
            # Redraw the canvas
            self.canvas_owq_graph_balance.draw()
            
            #Save figure
            self.dlg_owq_graph_balance.print_graph.clicked.connect(lambda _, b= [self.dlg_owq_graph_balance,self.canvas_owq_graph_balance]:self.figure_settings(b))
        
        except:
            # Clear canvas
            self.canvas_owq_graph_balance.figure.clear()
            self.ax_owq_graph_balance[0].clear()
            self.ax_owq_graph_balance[1].clear()
            self.canvas_owq_graph_balance.draw()
        
        
    def show_owq_graph(self):
        """Method to show the dialog with water quality graph"""
        #Delete radio buttons of pesticides
        if self.dlg_owq_graph.frame_3.layout() is not None:
            # Obtén el layout actual
            layout = self.dlg_owq_graph.frame_3.layout()
            
            # Elimina todos los widgets y elementos del layout (incluyendo espaciadores)
            while layout.count():
                item = layout.takeAt(0)
                widget = item.widget()
                if widget is not None:
                    widget.deleteLater()  # Elimina el widget
                elif item.spacerItem() is not None:
                    layout.removeItem(item)  # Elimina el espaciador

        else:
            # Si no hay un layout, crea uno nuevo
            layout = QVBoxLayout()
            self.dlg_owq_graph.frame_3.setLayout(layout)
        
        
        #Obtain number of pesticides
        ruta = self.obtain_direction_prj(self.dlg_base.line_quality.text())
        if os.path.exists(ruta):
            #Obtain values
            with open(ruta, "r") as archivo:
                lineas = archivo.readlines()
            self.data_owq_graph = {}
            pesticide = 0
            for i in range(len(lineas)):
                if lineas[i] == " Huang & van Genuchten (1995) CDE analytical solution\n":
                        pesticide += 1
                if lineas[i] == "      Z(m)      C(mg/L)      S(mg/mg)\n":
                    valores = []
                    for k in range(i+2,len(lineas)):
                        if len(lineas[k].split())==0 or (float(lineas[k].split()[1])==float(0)) and (float(lineas[k].split()[2])==float(0)):
                            self.data_owq_graph[pesticide] = valores
                            break
                        else:
                            valores.append([float(x) for x in lineas[k].split()])
            
            
            
            #Add number of pesticides
            for i in range(len(lineas)):
                if lineas[i][:44] == "Parameters for Water Quality - No. Compounds":
                        pesticide = int(lineas[i].split("=")[-1])
                        
            #Add pesticides
            # Agrega el QLabel
            label = QLabel("Select pesticide")
            layout.addWidget(label)

            # Lista de nombres para los QRadioButtons
            pesticides = [f"Pesticide {x+1}" for x in range(pesticide)]
            self.dictionary_radio_inputs_pesticides = {}

            # Crear y añadir varios QRadioButton
            for opcion in pesticides:
                radio_button = QRadioButton(opcion)
                # Conectar la función solo una vez
                radio_button.toggled.connect(lambda checked, rb=radio_button: self.update_owq_graph(rb.text()) if checked else None)
                self.dictionary_radio_inputs_pesticides[radio_button] = opcion
                layout.addWidget(radio_button)

            # Añade un espaciador para ajustar la posición
            spacer = QSpacerItem(20, 40, QSizePolicy.Minimum, QSizePolicy.Expanding)
            layout.addItem(spacer)

            # Selecciona el primer QRadioButton
            if self.dictionary_radio_inputs_pesticides:
                list(self.dictionary_radio_inputs_pesticides.keys())[0].setChecked(True)
                    
            #Show dialog
            self.dlg_owq_graph.show()
            self.dlg_owq_graph.raise_()
            

    def update_owq_graph(self,pesticide):
        """Method to update the dialog with water quality graph"""
        #Obtain data
        number_pesticide = int(pesticide.split()[-1])
        valores = self.data_owq_graph[number_pesticide]
        df = pd.DataFrame(valores, columns=["z","c","s"])
        
        #Create graph
        #Add layout
        #If canvas exist then clear. If not then create it. 
        if not hasattr(self, 'canvas_owq_graph'):
            # Si no existe, crear el canvas y añadirlo al layout
            self.canvas_owq_graph = FigureCanvas(plt.Figure(figsize=(15, 6)))
            
            # Asignar un layout al QFrame si no tiene uno
            layout = QVBoxLayout(self.dlg_owq_graph.frame)
            self.dlg_owq_graph.frame.setLayout(layout)
            
            # Añadir el canvas al layout
            layout.addWidget(self.canvas_owq_graph)
            
        else:
            # Si ya existe, simplemente limpiar el canvas
            self.canvas_owq_graph.figure.clear()
    
        self.ax_owq_graph= self.canvas_owq_graph.figure.subplots(1,2)
    
        # Clear canvas
        self.ax_owq_graph[0].clear()
        self.ax_owq_graph[1].clear()
        
        #Create graph

        # Crear el gráfico de barras
        profundidad = df["z"]
        concentracion = df["c"]
        ratio = df["s"]
        
        # Graficar concentración vs. profundidad
        self.ax_owq_graph[0].plot(concentracion, profundidad, marker='o', color='#007FFF')
        self.ax_owq_graph[1].plot(ratio, profundidad, marker='o', color='#007FFF')
        
        #Change y axis to limit to the maximum among all the pesticides. Same with x values.
        all_depths = [sublista[0] for pesticide in self.data_owq_graph.values() for sublista in pesticide]
        all_water_concentrations = [sublista[1] for pesticide in self.data_owq_graph.values() for sublista in pesticide]
        all_phases = [sublista[2] for pesticide in self.data_owq_graph.values() for sublista in pesticide]
        
        self.ax_owq_graph[0].set_ylim(-max(all_depths)*0.05, max(all_depths)*1.05)
        self.ax_owq_graph[1].set_ylim(-max(all_depths)*0.05, max(all_depths)*1.05)
        self.ax_owq_graph[0].set_xlim(-max(all_water_concentrations)/10,max(all_water_concentrations)*1.05)
        self.ax_owq_graph[1].set_xlim(-max(all_phases)/10,max(all_phases)*1.05)

        
        # Invertir el eje y para que 0 esté arriba y aumentar hacia abajo
        self.ax_owq_graph[0].invert_yaxis()
        self.ax_owq_graph[1].invert_yaxis()

        # Etiquetas de los ejes
        self.ax_owq_graph[0].set_xlabel('Pore water concentration, C\n(mg/L)', color='black',weight = "bold",fontsize=10)
        self.ax_owq_graph[1].set_xlabel('Solid phase concentration, S\n(mg/mg)', color='black',weight = "bold",fontsize=10)
        self.ax_owq_graph[0].set_ylabel('Depth (m)', color='black',weight = "bold",fontsize=10)

        # Colorear del mixing layer
        #Primero obtener el valor del mixing layer
        condition = False
        contador = 0
        with open(self.obtain_direction_prj(self.dlg_base.line_quality.text()), "r") as archivo:
            lineas_owq = archivo.readlines()
        for i in lineas_owq:
            if i.split("=")[0]=="  Mixing layer thickness (dml)":
                mixing_layer_thickness= float(i.split("=")[1].split()[0])/100
                        
        self.ax_owq_graph[0].axhspan(0, mixing_layer_thickness, facecolor='gray', alpha=0.3)  # Opacidad del rectángulo
        self.ax_owq_graph[1].axhspan(0, mixing_layer_thickness, facecolor='gray', alpha=0.3)  # Opacidad del rectángulo
        
        # Añadir texto "mixing layer" dentro del rectángulo con flechas más a la derecha
        self.ax_owq_graph[0].text(max(all_water_concentrations)*0.17, 0.01, 'Mixing \nLayer', fontsize=10, ha='center', va='center')
        self.ax_owq_graph[1].text(max(all_phases)*0.17, 0.01, 'Mixing \nLayer', fontsize=10, ha='center', va='center')

        # Colorear los ejes en negro
        self.ax_owq_graph[0].spines['bottom'].set_color('black')
        self.ax_owq_graph[1].spines['bottom'].set_color('black')
        self.ax_owq_graph[0].spines['top'].set_color('black')
        self.ax_owq_graph[1].spines['top'].set_color('black')
        self.ax_owq_graph[0].spines['left'].set_color('black')
        self.ax_owq_graph[1].spines['left'].set_color('black')
        self.ax_owq_graph[0].spines['right'].set_color('black')
        self.ax_owq_graph[1].spines['right'].set_color('black')
        
        
        
        #Change background color
        self.canvas_owq_graph.figure.set_facecolor('#f0f0f0')
        self.ax_owq_graph[0].set_facecolor('#f0f0f0')
        self.ax_owq_graph[1].set_facecolor('#f0f0f0')
        
        #Space beteween two graphs
        self.canvas_owq_graph.figure.subplots_adjust(wspace=0.6) #spacing beteween two graphs
        # Adjust bottom margin. If not then the graph is too big and I dont know how to change the graph size
        self.canvas_owq_graph.figure.subplots_adjust(left=0.2, bottom=0.2)

        # Redraw the canvas
        self.canvas_owq_graph.draw()
        
        #Save figure
        self.dlg_owq_graph.print_graph.clicked.connect(lambda _, b= [self.dlg_owq_graph,self.canvas_owq_graph]:self.figure_settings(b))
    
        
    
    def show_ohy_graphs(self):
        """Method to show ohy graph results"""
        #Obtain results
        ruta = self.obtain_direction_prj(self.dlg_base.line_hydrograph_2.text())
        with open(ruta, "r") as archivo:
            lineas = archivo.readlines()
        
        #Obtain results
        self.time_ohy= []
        self.outflow_ohy= []
        self.inflow_ohy = []
        self.infiltration_ohy = []
        self.rainfall_ohy = []
        self.wetting_front_ohy = []
        for i in range(len(lineas)):
            if "ie =r-f" in lineas[i]:
                for k in range(i+3,len(lineas)):
                    self.time_ohy.append(float(lineas[k].split()[0]))
                    self.outflow_ohy.append(float(lineas[k].split()[1]))
                    self.rainfall_ohy.append(float(lineas[k].split()[3])+float(lineas[k].split()[6]))
                    self.inflow_ohy.append(float(lineas[k].split()[4]))
                    self.infiltration_ohy.append(float(lineas[k].split()[6]))
                    self.wetting_front_ohy.append(float(lineas[k].split()[7]))
        
        #Put graph
        #If canvas exist then clear. If not then create it. 
        if not hasattr(self, 'canvas_ohy_graph'):
            # Si no existe, crear el canvas y añadirlo al layout
            self.canvas_ohy_graph = FigureCanvas(plt.Figure(figsize=(15, 6)))
            
            # Asignar un layout al QFrame si no tiene uno
            layout = QVBoxLayout(self.dlg_ohy_graphs.frame)
            self.dlg_ohy_graphs.frame.setLayout(layout)
            
            # Añadir el canvas al layout
            layout.addWidget(self.canvas_ohy_graph)
            
        else:
            # Si ya existe, simplemente limpiar el canvas
            self.canvas_ohy_graph.figure.clear()
        
        self.ax_ohy_graph= self.canvas_ohy_graph.figure.subplots()
        self.ax_precipitation_ohy = self.ax_ohy_graph.twinx()  
        
        #Update graph
        self.update_ohy_graphs()
        
        #Show dialog
        self.dlg_ohy_graphs.show()
        self.dlg_ohy_graphs.raise_()
        
    def update_ohy_graphs(self):
        """Method to update ohy graphs"""
        #Clear graph
        self.ax_ohy_graph.clear()
        self.ax_precipitation_ohy.clear()
        #Create graph
        if self.dlg_ohy_graphs.instantaneous.isChecked():
            #Precipitation
            bars = self.ax_precipitation_ohy.bar(self.time_ohy, self.rainfall_ohy,width = self.time_ohy[1]-self.time_ohy[0] ,color = "blue", 
                label="Rainfall",zorder = 1,alpha = 0.3)
            #Add lines
            #Inflow
            line_inflow, = self.ax_ohy_graph.plot(self.time_ohy, self.inflow_ohy, color="olive",label="Inflow hydrograph",zorder = 2)
            #Outflow
            line_outflow, = self.ax_ohy_graph.plot(self.time_ohy, self.outflow_ohy, color="forestgreen",label="Outflow hydrograph",zorder = 2)
            
            
            
            #Legend
            # Ajustar la leyenda combinada
            lines1, labels1 = self.ax_ohy_graph.get_legend_handles_labels()
            lines2, labels2 = self.ax_precipitation_ohy.get_legend_handles_labels()
            legend = self.ax_ohy_graph.legend(lines1 + lines2, labels1 + labels2, 
                loc="lower center",  # Centrar horizontalmente
                bbox_to_anchor=(0.5,-0.47),  # Posición justo arriba del gráfico
                ncol=3,  # Número de columnas en la leyenda
                frameon=False)
            
            #Change color legend
            legend.get_frame().set_facecolor("#f0f0f0")
        
            
            #Thousand separator
            def xfunc(x,pos):
                s = '{:0,d}'.format(int(x))
                return s
            x_format = tkr.FuncFormatter(xfunc)
            self.ax_ohy_graph.xaxis.set_major_formatter(x_format)

            #Quit precipitation grid
            self.ax_precipitation_ohy.grid(False)
            
            #Y limit for precipitation
            self.ax_precipitation_ohy.set_ylim(0, max(self.rainfall_ohy)*2)

            
            #Invert y axis for precipitation
            self.ax_precipitation_ohy.invert_yaxis()  # Invertir el eje y
            
            #Axis names
            self.ax_ohy_graph.set_xlabel("Time (s)")
            self.ax_ohy_graph.set_ylabel("Discharge (m$^{3}$/s)")
            self.ax_precipitation_ohy.set_ylabel("Rainfall (m/s)")
            self.ax_precipitation_ohy.yaxis.set_label_position("right") 
            
            #Graph title
            self.ax_ohy_graph.set_title("Instantaneous flow graph",color = "black")
            
            #Change background color
            self.canvas_ohy_graph.figure.set_facecolor('#f0f0f0')
            self.ax_ohy_graph.set_facecolor('#f0f0f0')
            # Ajustar los márgenes para añadir más espacio por debajo y por la izquierda
            self.canvas_ohy_graph.figure.subplots_adjust(left=0.15, bottom=0.25,right=0.85)
            #Draw canvas
            self.canvas_ohy_graph.draw()
        
        elif self.dlg_ohy_graphs.cumulative.isChecked():
            #Add lines
            #Precipitation
            self.ax_precipitation_ohy.bar(self.time_ohy, self.rainfall_ohy,width = self.time_ohy[1]-self.time_ohy[0] ,color = "blue", 
                label="Rainfall", zorder = 1,alpha = 0.3)
            #Inflow
            self.ax_ohy_graph.plot(self.time_ohy, np.cumsum(self.inflow_ohy), color="olive",label="Cumulative Inflow", zorder = 2)
            #Outflow
            self.ax_ohy_graph.plot(self.time_ohy, np.cumsum(self.outflow_ohy), color="forestgreen",label="Cumulative Outflow", zorder = 3)
            
            
            #Legend
            # Ajustar la leyenda combinada
            lines1, labels1 = self.ax_ohy_graph.get_legend_handles_labels()
            lines2, labels2 = self.ax_precipitation_ohy.get_legend_handles_labels()
