    def obtain_optimized_vfs_sensitivity_design(self):
        """Method to obtain the buffer length to analyze sensitivity"""
        #Create new df with required columns
        input_parameters = list(self.dic_data.keys())
        dic_save_data = {}
        for output in self.outputs_sensitivity_design.keys():
            values = []
            for i in self.param_values: 
                df_concat = self.results_sensitivity_raw.copy()
                for k in range(len(i)): 
                    df_concat = df_concat[df_concat[input_parameters[k]]==i[k]]
                    
                    
                x_values = self.buffer_lengths_sensitivity_design
                threshold = self.outputs_sensitivity_design[output]
                
                y_values = list(df_concat[output])
                y_values = y_values[:len(x_values)]
                #Quit nans and -1 (error in execution) and only do interpolation if there are at least to values
                values_together = [(x_values[x],y_values[x]) for x in range(len(x_values))]
                x_values = [x[0] for x in values_together if pd.notna(x[1]) and x[1]!=-1.0]
                y_values = [x[1] for x in values_together if pd.notna(x[1]) and x[1]!=-1.0]
                
                if len(y_values)>1:
                    try:
                        if threshold>=min(y_values) and threshold<=max(y_values):#if delivery ratio is between values, then interpolate
                            f = interp1d(y_values, x_values)
                            value = round(f(threshold).item(),2)
                        #if delivery ratio is below or higher, then extrapolate
                        elif threshold<min(y_values):
                            slope = (x_values[-1]-x_values[-2])/(y_values[-1]-y_values[-2])
                            value = x_values[-1] + slope*(threshold - y_values[-1])
                        elif threshold>max(y_values):
                            slope = (x_values[0]-x_values[1])/(y_values[0]-y_values[1])
                            value = x_values[0] + slope*(threshold-y_values[0])
                        if value<0:
                            value = 0
                    except ZeroDivisionError:
                        value = "Error"
                else:
                    value = "Error"
                    
                
                values.append(value)
            
            dic_save_data[f"Buffer Length {output} {self.outputs_sensitivity_design[output]}"] = values
                

        #Create df        
        data_input_parameters = {}     
        for k,i in enumerate(self.dic_data.keys()):
            values = []
            for p in self.param_values: 
                values.append(p[k])
            data_input_parameters[i] = values
        data_input_parameters.update(dic_save_data)
        df = pd.DataFrame(data = data_input_parameters)
        
        #If there have been errors in the interpolation with buffer lengths then interpolate with parameters (as in sensitivity analysis). For a sensitivity analysis we can not have no data values.
        input_parameters = list(self.dic_data.keys())
        inputs = df[input_parameters]
        output_columns = [f"Buffer Length {x} {self.outputs_sensitivity_design[x]}" for x in self.outputs_sensitivity_design.keys()]
        outputs = df[output_columns]
        # Filtrar los datos completos (sin valores NaN en outputs)
        for output in output_columns:
            mask = df[output] != "Error"
            inputs_complete = inputs[mask]
            outputs_complete = outputs[mask]
            if len(inputs_complete)<len(df): #if there are less inputs without errors than original df then there are errors
                try:
                    #Create model of linear regression
                    #Train
                    X_train = inputs_complete.to_numpy()
                    y_train = outputs_complete[output].to_numpy()
                    X_train_design = np.hstack([np.ones((X_train.shape[0], 1)), X_train])
                    coef, residuals, rank, s = np.linalg.lstsq(X_train_design, y_train, rcond=None)
                    #Predict
                    X_test = inputs[~mask].to_numpy()
                    X_test_design = np.hstack([np.ones((X_test.shape[0], 1)), X_test])
                    pred_output = X_test_design @ coef
                    pred_output = np.maximum(pred_output, 0)
                    df.loc[~mask, output] = pred_output
                    
                except: #if error in prediction then put average
                    df.loc[~mask, output] = float(np.mean(outputs_complete[output]))
        
        #See if there is an output column with all nans
        error_columns = []
        for c in df.columns:
            if df[c].isna().all():  
                error_columns.append(c)
                df.drop(c,axis = 1,inplace = True)
        
        return df,error_columns
    
    def create_df_design(self,results):
        """Method to create the dataframe of design after parallelization"""
        #First create dataframe
        df = pd.DataFrame(columns=list(results[0].columns))
        for i in results:
            df = pd.concat([df,i], ignore_index=True)
        #Put in the same order as the input values
        new_df = pd.DataFrame(columns=list(results[0].columns))
        input_parameters = ["Rainfall (mm)"]
        combinations_design = [x[0] for x in self.combinations_design]
        if self.dlg_base.design_length.isChecked():
            input_parameters += ["VFS Length (m)"]
            combinations_design = [[combinations_design[x],self.combinations_design[x][1]] for x in range(len(combinations_design))]
        if self.dlg_base.design_spacing.isChecked():
            input_parameters += ["Vegetation Spacing (cm)"]
            combinations_design = [[combinations_design[x],self.combinations_design[x][2]] for x in range(len(combinations_design))]
        for i in combinations_design:
            df_concat = df.copy()
            for k in range(len(i)): 
                df_concat = df_concat[df_concat[input_parameters[k]]==i[k]]
            df_concat = df_concat.iloc[[0]]
            new_df = pd.concat([new_df,df_concat], ignore_index=True)
        return new_df
    
    def create_df_sensitivity(self,results):
        """Method to create the dataframe of sensitivity after parallelization"""
        #First create dataframe
        df = pd.DataFrame(columns=list(results[0].columns))
        for i in results:
            df = pd.concat([df,i], ignore_index=True)
        #Put in the same order as the input values
        new_df = pd.DataFrame(columns=list(results[0].columns))
        input_parameters = list(self.dic_data.keys())
        for i in self.param_values:
            df_concat = df.copy()
            for k in range(len(i)): 
                df_concat = df_concat[df_concat[input_parameters[k]]==i[k]]
            df_concat = df_concat.iloc[[0]]
            new_df = pd.concat([new_df,df_concat], ignore_index=True)
        #If there are errors then make a linear regression to add data
        inputs = new_df[input_parameters]
        self.number_outputs = len(new_df.columns)-len(input_parameters)-1
        output_columns = new_df.columns[-self.number_outputs:].tolist()
        outputs = new_df[output_columns]
        # Filtrar los datos completos (sin valores NaN en outputs)
        mask = new_df['Error'] == 0
        inputs_complete = inputs[mask]
        outputs_complete = outputs[mask]
        if len(inputs_complete) == 0: #all rows are error
            return "error","error"
        if len(inputs_complete)<len(new_df): #if there are less inputs without errors than original df then there are errors
            for output in output_columns:
                try:
                    #Create model of linear regression
                    #Train
                    X_train = inputs_complete.to_numpy()
                    y_train = outputs_complete[output].to_numpy()
                    X_train_design = np.hstack([np.ones((X_train.shape[0], 1)), X_train])
                    coef, residuals, rank, s = np.linalg.lstsq(X_train_design, y_train, rcond=None)
                    #Predict
                    X_test = inputs[~mask].to_numpy()
                    X_test_design = np.hstack([np.ones((X_test.shape[0], 1)), X_test])
                    pred_output = X_test_design @ coef
                    pred_output = np.maximum(pred_output, 0)
                    new_df.loc[~mask, output] = pred_output
                except: #if error in prediction then put average
                    new_df.loc[~mask, output] = np.mean(outputs_complete[output])
        #If there are nans values and but not errors also they have to be changed
        for output in output_columns:
            mask = df[output].notna()
            inputs_complete = inputs[mask]
            outputs_complete = outputs[mask]
            if len(inputs_complete)<len(df): #if there are less inputs without errors than original df then there are errors
                try:
                    #Create model of linear regression
                    #Train
                    X_train = inputs_complete.to_numpy()
                    y_train = outputs_complete[output].to_numpy()
                    X_train_design = np.hstack([np.ones((X_train.shape[0], 1)), X_train])
                    coef, residuals, rank, s = np.linalg.lstsq(X_train_design, y_train, rcond=None)
                    #Predict
                    X_test = inputs[~mask].to_numpy()
                    X_test_design = np.hstack([np.ones((X_test.shape[0], 1)), X_test])
                    pred_output = X_test_design @ coef
                    pred_output = np.maximum(pred_output, 0)
                    new_df.loc[~mask, output] = pred_output
                        
                except: #if error in prediction then put average
                    new_df.loc[~mask, output] = np.mean(outputs_complete[output])
        #See if there is an output column with all nans
        error_columns = []
        for c in new_df.columns:
            if new_df[c].isna().all():  
                error_columns.append(c)
                new_df.drop(c,axis = 1,inplace = True)
        
        return new_df,error_columns
    
    def create_df_sensitivity_design(self,results):
        """Method to create the dataframe of sensitivity after parallelization for design"""
        #First create dataframe
        df = pd.DataFrame(columns=list(results[0].columns))
        for i in results:
            df = pd.concat([df,i], ignore_index=True)
        
        #Put in the same order as the input values
        new_df = pd.DataFrame(columns=list(results[0].columns))
        input_parameters = list(self.dic_data.keys())
        
        for i in self.param_values:
            df_concat = df.copy()
            for k in range(len(i)): 
                df_concat = df_concat[df_concat[input_parameters[k]]==i[k]]
            for v in self.buffer_lengths_sensitivity_design:
                df_concat_2 = df_concat[df_concat["Buffer length (m)"]==v]
                df_concat_2 = df_concat_2.iloc[[0]]
                new_df = pd.concat([new_df,df_concat_2], ignore_index=True)
