    def run_uncertainity_analysis_part_one(self):
        """Method to run parallel processing of uncertainity analysis"""
        #After clicking to run disconnect it because if it is clicked twice then it can give error
        self.dlg_base.run_uncertainity.clicked.disconnect(self.run_uncertainity_analysis_part_one)
        #Create the dictionary for the sensitivity analysis
        try:
            self.dic_data = self.create_dictionary_uncertainity_analysis()
        except Exception as e:
            self.warning_message("Error:"+str(e))
            #Connect again signal
            self.dlg_base.run_uncertainity.clicked.connect(self.run_uncertainity_analysis_part_one)
            return
        
        #Check if all the parameters that the user has choosen are available in the project
        error_parameters = self.check_inputs_exist_sensitivity_analysis(self.obtain_direction_vfsmod(self.dlg_base.vfs_file_uncertainity.text()))
        
        if len(error_parameters)>0:
            if len(error_parameters)==1:
                self.warning_message(f"{','.join(error_parameters)} is not in your original project. \nPlease delete it here or add it to the project.")
            else:
                self.warning_message(f"{','.join(error_parameters)} are not in your original project. \nPlease delete them here or add them to the project.")
            #Connect signal again
            self.dlg_base.run_uncertainity.clicked.connect(self.run_uncertainity_analysis_part_one)
            return
            
        self.vfs_uncertainity_file = self.dlg_base.vfs_file_uncertainity.text()
        
        #Warning
        if int(self.dlg_base.samples_uncertainity.text())<256:
            self.warning_message("N value must be higher than 256 when executing Uncertainty Analysis")
            #Connect signal again
            self.dlg_base.run_uncertainity.clicked.connect(self.run_uncertainity_analysis_part_one)
            return
        
        #We will use the fast sample to obtain randomized samples for each input
        values = []
        for parameter in self.dic_data.keys():
            #Create problem variable
            self.problem = {'num_vars': 1,'names': [parameter],'bounds': [self.dic_data[parameter][1]],"dists":[self.dic_data[parameter][0]]}
            #Create samples
            samples = sample_fast(self.problem, int(self.dlg_base.samples_uncertainity.text()), M = 1)
            values.append(samples)
        
        self.param_values = np.column_stack(values)

        #We start obtaining the results
        #Create folders of uncertainity analysis
        self.create_folder_uncertainity_analysis()
        
        #Move files to uncertainity analysis folder
        self.move_files_uncertainity_analysis()
        
        #Create dataframe to save the results
        self.results_sensitivity = pd.DataFrame(columns=["Error","Total Runoff from Source (mm depth over Source Area)","Total Runoff from Source (m3)",
            "Total Runoff out from Filter (mm depth over Source+Filter)","Total Runoff out from Filter (m3)","Total Infiltration in Filter (m3)",
            "Mass Sediment Input to Filter (kg)","Concentration Sediment in Runoff from source Area (g/L)",
            "Mass Sediment Output from Filter (kg)","Concentration Sediment in Runoff exiting the Filter (g/L)",
            "Sediment Delivery Ratio","Runoff Delivery Ratio","Wetting Front Depth (m)"])
        
        
        number_outputs = len(self.results_sensitivity.columns)-1
        #Add the parameters names 
        for i in self.dic_data.keys():
            self.results_sensitivity.insert(0,i,None)
        
        
        #Obtain number of pesticides 
        self.number_pesticides = self.obtain_number_pestidides(self.obtain_direction_vfsmod(self.dlg_base.vfs_file_uncertainity.text()))
        
        #Method were the paralelization is achieved
        self.start_analysis_uncertainity()
        
        
    def run_uncertainity_analysis_part_two(self):
        """Second part of uncertainity analysis to analyze the results. I have splitted uncertainity running
        in two because we use Thread method and we need to stop till the thread finishes, if not we get an error"""
        #Create DataFrame or results
        self.results_sensitivity = self.create_df_uncertainity(self.results)
        
        #If all executions gave error then put warning
        if len(self.results_sensitivity[self.results_sensitivity["Error"]==1]) == len(self.results_sensitivity):
            #obtain the error of an execution to show it to the user
            error_in_execution = self.obtain_error_for_execution()
            self.warning_message(f"All executions gave error.\n Please check input data.\nThe error may be due to the following:\n{error_in_execution}",courier = True)
            #Connect signal again
            self.dlg_base.run_uncertainity.clicked.connect(self.run_uncertainity_analysis_part_one)
            return
        
        #Delete all files created for paralelization of sensitivity analysis
        self.delete_files_uncertainity()
            
        #Save results in CSV
        path = self.obtain_direction_vfsmod(self.dlg_base.file_save_uncertainity.text())
        try:
            with open(path, 'w') as f:
                f.write("Uncertainty analysis results" + '\n')
                string = f"Studied parameters:"
                for i in range(len(self.dic_data)):
                    string += list(self.dic_data.keys())[i]
                    if i!= len(self.dic_data)-1:
                        string +=","
                    else:
                        string += "\n"
                f.write(string)
        except PermissionError:
            self.warning_message(f"{path} file is opened and Uncertainty Analysis data could not be saved")
            #Connect signal again
            self.dlg_base.run_uncertainity.clicked.connect(self.run_uncertainity_analysis_part_one)
            return
        self.results_sensitivity.to_csv(path, mode='a',index=False, float_format='%.10f')
        
        #Add path to lineEdit and update graph
        self.dlg_base.csv_results_uncertainity.setText(self.dlg_base.file_save_uncertainity.text())
        self.show_graph_sensitivity_uncertainity()
        
        #Connect signal again
        self.dlg_base.run_uncertainity.clicked.connect(self.run_uncertainity_analysis_part_one)
        
        #Close progress bar and warning message of ending
        self.progress_metod(close = True)
        self.warning_message("Uncertainty analysis completed succesfully!")
    
    
    def move_files_design_analysis(self):
        """Method to move files to the corresponding folders for sensitiviy analysis"""
        #FIRST WE MOVE THE FILES TO THE FOLDER OF DESIGN ANALYSIS
        #Prj
        prj_file = str(Path(self.dlg_base.working_directory_vfsmod.text()+"/design/design.prj"))
        #Check if water quality is simulated
        with open(self.obtain_direction_vfsmod(self.dlg_base.design_vfs_file.text()), "r") as archivo:
            lineas = archivo.readlines()
        self.water_quality = False
        for i in lineas:
            if i[:3]=="iwq":
                self.water_quality = True
            
        #Create file
        with open(prj_file, 'w') as archivo:
            archivo.write(f"ikw={str(Path('inputs/design.ikw'))}  \n")
            archivo.write(f"iso={str(Path('inputs/design.iso'))}  \n")
            archivo.write(f"igr={str(Path('inputs/design.igr'))}  \n")
            archivo.write(f"isd={str(Path('inputs/design.isd'))}  \n")
            archivo.write(f"irn={str(Path('inputs/design.irn'))}  \n")
            archivo.write(f"iro={str(Path('inputs/design.iro'))}  \n")
            if self.water_quality:
                archivo.write(f"iwq={str(Path('inputs/design.iwq'))}  \n")
            archivo.write(f"og1={str(Path('output/design.og1'))}  \n") 
            archivo.write(f"og2={str(Path('output/design.og2'))}  \n")
            archivo.write(f"ohy={str(Path('output/design.ohy'))}  \n")
            archivo.write(f"osm={str(Path('output/design.osm'))}  \n")
            archivo.write(f"osp={str(Path('output/design.osp'))}  \n")
            if self.water_quality:
                archivo.write(f"owq={str(Path('output/design.owq'))}  \n")
        
        #UH
        lis_file = str(Path(self.dlg_base.working_directory_vfsmod.text()+"/design/design.lis"))
        #Create file
        with open(lis_file, 'w') as archivo:
            archivo.write(f"inp={str(Path('inputs/design.inp'))}  \n") 
            archivo.write(f"iro={str(Path('inputs/design.iro'))}  \n")
            archivo.write(f"irn={str(Path('inputs/design.irn'))}  \n")
            archivo.write(f"isd={str(Path('inputs/design.isd'))}  \n")
            archivo.write(f"out={str(Path('inputs/design.out'))}  \n")
            archivo.write(f"hyt={str(Path('inputs/design.hyt'))}  \n")
        
        #REST OF THE FILES
        #Function to copy and paste the inputs to create the files to use in the design analysis
        def copy_paste(process,type_input):
            ruta_pegar = str(Path(self.dlg_base.working_directory_vfsmod.text()+f"/design/inputs/design.{type_input}" ))
            if process == "UH":
                ruta = self.obtain_direction_vfsmod(self.dlg_base.design_uh_file.text())
            elif process == "VFS":
                ruta = self.obtain_direction_vfsmod(self.dlg_base.design_vfs_file.text())
            if os.path.exists(ruta) and os.path.isfile(ruta):
                #First we open .prj and obtain the direction of the copying file
                with open(ruta, "r") as archivo:
                    lineas = archivo.readlines()
                for i in lineas:
                    if i[:3]==type_input:
                        ikw = i.split("=")[-1]
                if not os.path.isabs(ikw): #relative path
                    ikw = os.path.join(os.path.dirname(ruta), ikw)
                ikw = ikw.rstrip() #take out the line jumps
                shutil.copyfile(ikw, ruta_pegar)
        #INP
        copy_paste("UH","inp")
        #OUT
        copy_paste("UH","out")
        #HYT
        copy_paste("UH","hyt")
        
        #IKW
        copy_paste("VFS","ikw")
        #ISO
        copy_paste("VFS","iso")
        #IGR
        copy_paste("VFS","igr")
        #ISD
        copy_paste("VFS","isd")
        #IRN
        copy_paste("VFS","irn")
        #IRO
        copy_paste("VFS","iro")
        #IWQ
        if self.water_quality:
            copy_paste("VFS","iwq")
        
        
        #Put base values
        self.modify_inp_file_design(duration = self.dlg_base.design_storm_duration.text())
        if not self.dlg_base.design_length.isChecked():
            self.modify_ikw_file_design()
        if not self.dlg_base.design_spacing.isChecked():
            self.modify_igr_file_design()
        
        #NOW WE REPLICATE THE FILES AS MUCH AS CORES ARE IN THE COMPUTER
        self.number_cores = psutil.cpu_count()
        
        #Replicate prj as much as cores are
        for core in range(self.number_cores*5):#we do *5 because if not there can be problems of overlapping:processes executing files that are already executing
            with open(prj_file, 'r') as file:
                lineas = file.readlines()
            lineas = [linea.replace("design",f"design_{core}") for linea in lineas]
            new_filepath = prj_file.replace("design.prj",f"design_{core}.prj")
            with open(new_filepath, 'w') as archivo:
                for i in lineas:
                    archivo.write(i)
        #Replicate lis as much as cores are
        for core in range(self.number_cores*5):
            with open(lis_file, 'r') as file:
                lineas = file.readlines()
            lineas = [linea.replace("design",f"design_{core}") for linea in lineas]
            new_filepath = lis_file.replace("design.lis",f"design_{core}.lis")
            with open(new_filepath, 'w') as archivo:
                for i in lineas:
                    archivo.write(i)
        #Move replicated input files 
        carpeta = str(Path(self.dlg_base.working_directory_vfsmod.text()+"/design"))
        folder_path = os.path.join(carpeta, "inputs")
        files = [f for f in os.listdir(folder_path) if os.path.isfile(os.path.join(folder_path, f)) and "_" not in f]
        for i in range(self.number_cores*5):
            for k in files:
                shutil.copyfile(str(Path(carpeta+"/inputs/"+k)), str(Path(carpeta+"/inputs/"+k.replace("design",f"design_{i}"))))
        #Replicate executables
        carpeta_bat = str(Path(self.plugin_directory+"/executables"))
        for core in range(self.number_cores*5):
            #In windows
            if sys.platform.startswith("win"):
                #Execution UH
                shutil.copyfile(str(Path(carpeta_bat+"/execution.bat")), str(Path(carpeta_bat+"/"+f"execution_uh_{core}.bat")))
                f = open(str(Path(carpeta_bat+"/"+f"execution_uh_{core}.bat")),"w+")
                linea_uno = "cd {}".format(f'"{str(Path(self.dlg_base.working_directory_vfsmod.text()+"/design/"))}"')
                linea_dos = f'"{str(Path(self.plugin_directory+"/executables/uh"))}" design_{core}.lis'
                linea_tres = "Pause"
                f.write("{} \n".format(linea_uno))
                f.write("{} \n".format(linea_dos))
                #f.write("{} \n".format(linea_tres))
                f.close()
                #Execution VFS
                shutil.copyfile(str(Path(carpeta_bat+"/execution.bat")), str(Path(carpeta_bat+"/"+f"execution_vfs_{core}.bat")))
                f = open(str(Path(carpeta_bat+"/"+f"execution_vfs_{core}.bat")),"w+")
                linea_uno = "cd {}".format(f'"{str(Path(self.dlg_base.working_directory_vfsmod.text()+"/design/"))}"')
                linea_dos = f'"{str(Path(self.plugin_directory+"/executables/vfsm"))}" design_{core}.prj'
                linea_tres = "Pause"
                f.write("{} \n".format(linea_uno))
                f.write("{} \n".format(linea_dos))
                #f.write("{} \n".format(linea_tres))
                f.close()
            #In mac
            elif sys.platform.startswith("darwin"):
                #Execution UH
                shutil.copyfile(str(Path("/Library/Application Support/vfsmod-gui"+"/executables/execution.sh")), str(Path("/Library/Application Support/vfsmod-gui/executables"+"/"+f"execution_uh_{core}.sh")))
                with open(str(Path("/Library/Application Support/vfsmod-gui"+f"/executables/execution_uh_{core}.sh")), "w", newline="\n") as f:
                    linea_uno = "#!/bin/bash\n"
                    linea_dos = "cd {}".format(f'"{str(Path(self.dlg_base.working_directory_vfsmod.text()+"/design/"))}"')
                    linea_tres = f'"{str(Path("/Library/Application Support/vfsmod-gui"+"/executables/uh"))}" design_{core}.lis'
                    f.write("{} \n".format(linea_uno))
                    f.write("{} \n".format(linea_dos))
                    f.write("{} \n".format(linea_tres))
                    f.close()
                #Execution VFS
                shutil.copyfile(str(Path("/Library/Application Support/vfsmod-gui/executables"+"/execution.sh")), str(Path("/Library/Application Support/vfsmod-gui/executables"+"/"+f"execution_vfs_{core}.sh")))
                with open(str(Path("/Library/Application Support/vfsmod-gui"+f"/executables/execution_vfs_{core}.sh")), "w", newline="\n") as f:
                    linea_uno = "#!/bin/bash\n"
                    linea_dos = "cd {}".format(f'"{str(Path(self.dlg_base.working_directory_vfsmod.text()+"/design/"))}"')
                    linea_tres = f'"{str(Path("/Library/Application Support/vfsmod-gui"+"/executables/vfsm"))}" design_{core}.prj'
                    f.write("{} \n".format(linea_uno))
                    f.write("{} \n".format(linea_dos))
                    f.write("{} \n".format(linea_tres))
                    f.close()
                
    
