    def update_graph_calibration_single(self):
        """Method to update the graph of calibration"""
        path = self.obtain_direction_vfsmod(self.dlg_calibration_results_single.results.text())
        if os.path.exists(path) and os.path.isfile(path):    
            #First add the text
            with open(path, "r") as archivo:
                lineas = archivo.readlines()
            contenido = ""
            data = {}
            for k,i in enumerate(lineas):
                if i==f"Observed vs predicted values: \n":
                    for m in lineas[k+1].split(","):
                        parameter = m.split(":")[0]
                        observed = float(m.split(":")[1].split("-")[0])
                        simulated = float(m.split(":")[1].split("-")[1])
                        data[parameter] = [observed,simulated]
                contenido += i
            self.dlg_calibration_results_single.textEdit.setPlainText(contenido)
            
            #Add the graph
            if not hasattr(self, 'canvas_calibration_graph_single'):
                #Create the canvas of the graph
                # Si no existe, crear el canvas y añadirlo al layout
                self.canvas_calibration_graph_single = FigureCanvas(plt.Figure(figsize=(15, 6)))
                # Asignar un layout al QFrame si no tiene uno
                layout = QVBoxLayout(self.dlg_calibration_results_single.frame)
                self.dlg_calibration_results_single.frame.setLayout(layout)
                #Add canvas to layout
                layout.addWidget(self.canvas_calibration_graph_single)
            
            #Add graph
            #Add graph
            self.canvas_calibration_graph_single.figure.clear()
            if len(data) == 1:
                self.ax_calibration_results_single = [self.canvas_calibration_graph_single.figure.subplots(1,len(data))]
            else:
                self.ax_calibration_results_single = self.canvas_calibration_graph_single.figure.subplots(1,len(data))
                self.canvas_calibration_graph_single.figure.subplots_adjust(wspace=1)
            
            
            for i,k in enumerate(data.keys()):
                #Add graph
                self.ax_calibration_results_single[i].bar("Observed", data[k][0], color='skyblue')
                self.ax_calibration_results_single[i].bar("Simulated", data[k][1], color='red')
                #Rotate ticks
                self.ax_calibration_results_single[i].set_xticks(["Observed", "Simulated"])
                self.ax_calibration_results_single[i].set_xticklabels(["Observed", "Simulated"], rotation=45)
                #Add values
                self.ax_calibration_results_single[i].text("Observed", data[k][0] + (data[k][0] * 0.05), f'{data[k][0]}', ha='center',family="arial",weight = "bold",color = "black")
                self.ax_calibration_results_single[i].text("Simulated", data[k][1] + (data[k][1] * 0.05), f'{round(data[k][1],3)}', ha='center',family="arial",weight = "bold",color = "black")
                #Add title x and y axis
                self.ax_calibration_results_single[i].set_ylabel(k)
                #Y limit
                self.ax_calibration_results_single[i].set_ylim(0, max(data[k][0],data[k][1])*1.1)
                #Change background color
                self.ax_calibration_results_single[i].set_facecolor('#f0f0f0')
            
            #Change background color
            self.canvas_calibration_graph_single.figure.set_facecolor('#f0f0f0')
            
            
            # Ajustar los márgenes para añadir más espacio por debajo y por la izquierda
            self.canvas_calibration_graph_single.figure.subplots_adjust(wspace=1) #spacing beteween two graphs
            self.canvas_calibration_graph_single.figure.subplots_adjust(left=0.1, bottom=0.2)
            #Draw canvas
            self.canvas_calibration_graph_single.draw()
            
            #Save figure
            self.dlg_calibration_results_single.print_graph.clicked.connect(lambda _, b= [self.dlg_calibration_results_single,self.canvas_calibration_graph_single]:self.figure_settings(b))
            
            
            
    def update_bat_calibration(self):
        """Method to update the bat of the hydrograph"""
        #In windows
        if sys.platform.startswith("win"):
            f = open(str(Path(self.plugin_directory+"/executables/execution.bat")),"w+")
            linea_uno = "cd {}".format(f'"{str(Path(self.dlg_base.working_directory_vfsmod.text()+"/inverse/"))}"')
            linea_dos = f'"{str(Path(self.plugin_directory+"/executables/vfsm"))}" inverse.prj'
            linea_tres = "Pause"
            f.write("{} \n".format(linea_uno))
            f.write("{} \n".format(linea_dos))
            #f.write("{} \n".format(linea_tres))
            f.close()
        #In mac
        elif sys.platform.startswith("darwin"):
            with open(str(Path("/Library/Application Support/vfsmod-gui"+"/executables/execution.sh")), "w", newline="\n") as f:
                linea_uno = "#!/bin/bash\n"
                linea_dos = "cd {}".format(f'"{str(Path(self.dlg_base.working_directory_vfsmod.text()+"/inverse/"))}"')
                linea_tres = f'"{str(Path("/Library/Application Support/vfsmod-gui"+"/executables/vfsm"))}" inverse.prj'
                f.write("{} \n".format(linea_uno))
                f.write("{} \n".format(linea_dos))
                f.write("{} \n".format(linea_tres))
                f.close()
    
    def move_files_calibration_hydrograph(self):
        """Method to move files to the corresponding folders for calibration"""
        #Move hydrograph
        try:
            shutil.copyfile(str(Path(self.obtain_direction_vfsmod(self.dlg_base.hydrograph_file.text()))),str(Path(self.dlg_base.working_directory_vfsmod.text()+f"/inverse/{os.path.basename(self.dlg_base.hydrograph_file.text())}")))
        except SameFileError:
            pass
            
        #Prj
        prj_file = str(Path(self.dlg_base.working_directory_vfsmod.text()+"/inverse/inverse.prj"))
        #Check if water quality is simulated
        with open(os.path.normpath(self.obtain_direction_vfsmod(self.dlg_base.vfs_project.text())), "r") as archivo:
            lineas = archivo.readlines()
        self.water_quality = False
        for i in lineas:
            if i[:3]=="iwq":
                self.water_quality = True
            
        #Create file
        with open(prj_file, 'w') as archivo:
            archivo.write(f"ikw={str(Path('inputs/inverse.ikw'))}  \n")
            archivo.write(f"iso={str(Path('inputs/inverse.iso'))}  \n")
            archivo.write(f"igr={str(Path('inputs/inverse.igr'))}  \n")
            archivo.write(f"isd={str(Path('inputs/inverse.isd'))}  \n")
            archivo.write(f"irn={str(Path('inputs/inverse.irn'))}  \n")
            archivo.write(f"iro={str(Path('inputs/inverse.iro'))}  \n")
            if self.water_quality:
                archivo.write(f"iwq={str(Path('inputs/inverse.iwq'))}  \n")
            archivo.write(f"og1={str(Path('output/inverse.og1'))}  \n") 
            archivo.write(f"og2={str(Path('output/inverse.og2'))}  \n")
            archivo.write(f"ohy={str(Path('output/inverse.ohy'))}  \n")
            archivo.write(f"osm={str(Path('output/inverse.osm'))}  \n")
            archivo.write(f"osp={str(Path('output/inverse.osp'))}  \n")
            if self.water_quality:
                archivo.write(f"owq={str(Path('output/inverse.owq'))}  \n")
        
        #UH
        lis_file = str(Path(self.dlg_base.working_directory_vfsmod.text()+"/inverse/inverse.lis"))
        #Create file
        with open(lis_file, 'w') as archivo:
            archivo.write(f"inp={str(Path('inputs/inverse.inp'))}  \n") 
            archivo.write(f"iro={str(Path('inputs/inverse.iro'))}  \n")
            archivo.write(f"irn={str(Path('inputs/inverse.irn'))}  \n")
            archivo.write(f"isd={str(Path('inputs/inverse.isd'))}  \n")
            archivo.write(f"out={str(Path('inputs/inverse.out'))}  \n")
            archivo.write(f"hyt={str(Path('inputs/inverse.hyt'))}  \n")
        
        #REST OF THE FILES
        #Function to copy and paste the inputs to create the files to use in the design analysis
        def copy_paste(type_input):
            ruta_pegar = str(Path(self.dlg_base.working_directory_vfsmod.text()+f"/inverse/inputs/inverse.{type_input}")) 
            ruta = self.obtain_direction_vfsmod(self.dlg_base.vfs_project.text())
            if os.path.exists(ruta) and os.path.isfile(ruta):
                #First we open .prj and obtain the direction of the copying file
                with open(ruta, "r") as archivo:
                    lineas = archivo.readlines()
                for i in lineas:
                    if i[:3]==type_input:
                        ikw = i.split("=")[-1]
                if not os.path.isabs(ikw): #relative path
                    ikw = os.path.join(os.path.dirname(ruta), ikw)
                ikw = ikw.rstrip() #take out the line jumps
                shutil.copyfile(ikw, ruta_pegar)
        
        #IKW
        copy_paste("ikw")
        #ISO
        copy_paste("iso")
        #IGR
        copy_paste("igr")
        #ISD
        copy_paste("isd")
        #IRN
        copy_paste("irn")
        #IRO
        copy_paste("iro")
        #IWQ
        if self.water_quality:
            copy_paste("iwq")
    
    def create_dictionary_calibration_logarithmic(self,dictionary):
        """Method to convert the ranges in logatithmic if the range is too big"""
        logarithmic_inputs = []
        for i in dictionary.keys():
            minimum = dictionary[i][0]
            maximum = dictionary[i][1]
            if maximum>(minimum*1000):
                dictionary[i][0] = np.log10(minimum)
                dictionary[i][1] = np.log10(maximum)
                logarithmic_inputs.append(i)
                
        return dictionary,logarithmic_inputs
        
    def create_dictionary_calibration_hydrograph(self):
        """Method to create the dictionary of bounds of the input parameters for the calibration of hydrograph"""
        #Inputs
        dictionary = {}
        #Function to return the value needed for the inverse calibration file
        def calibration(radio_button_one,radio_button_two):
            if radio_button_one.isChecked():
                return "change"
            elif radio_button_two.isChecked():
                return "calibrate"
            else:
                return -1
        
        
        vertical = calibration(self.dlg_hydrograph_calibration.change_vertical,self.dlg_hydrograph_calibration.calibrate_vertical)
        average = calibration(self.dlg_hydrograph_calibration.change_average,self.dlg_hydrograph_calibration.calibrate_average)
        saturated = calibration(self.dlg_hydrograph_calibration.change_saturated,self.dlg_hydrograph_calibration.calibrate_saturated)
        initial = calibration(self.dlg_hydrograph_calibration.change_initial,self.dlg_hydrograph_calibration.calibrate_initial)
        maximum = calibration(self.dlg_hydrograph_calibration.change_maximum,self.dlg_hydrograph_calibration.calibrate_maximum)
        fraction = calibration(self.dlg_hydrograph_calibration.change_fraction,self.dlg_hydrograph_calibration.calibrate_fraction)
        width = calibration(self.dlg_hydrograph_calibration.change_width,self.dlg_hydrograph_calibration.calibrate_width)
        length = calibration(self.dlg_hydrograph_calibration.change_length,self.dlg_hydrograph_calibration.calibrate_length)
        manning = calibration(self.dlg_hydrograph_calibration.change_manning,self.dlg_hydrograph_calibration.calibrate_manning)
        slope = calibration(self.dlg_hydrograph_calibration.change_slope,self.dlg_hydrograph_calibration.calibrate_slope)
        
        water_depth = calibration(self.dlg_hydrograph_calibration.change_depth,self.dlg_hydrograph_calibration.calibrate_depth)
        soil_saturated = calibration(self.dlg_hydrograph_calibration.change_ansiotropy,self.dlg_hydrograph_calibration.calibrate_ansiotropy)
        soil_or = calibration(self.dlg_hydrograph_calibration.change_soil_or,self.dlg_hydrograph_calibration.calibrate_soil_or)
        soil_vgalpha = calibration(self.dlg_hydrograph_calibration.change_soil_vgalpha,self.dlg_hydrograph_calibration.calibrate_soil_vgalpha)
        soil_vgn = calibration(self.dlg_hydrograph_calibration.change_soil_vgn,self.dlg_hydrograph_calibration.calibrate_soil_vgn)
        soil_vgm = calibration(self.dlg_hydrograph_calibration.change_soil_vgm,self.dlg_hydrograph_calibration.calibrate_soil_vgm)
        soil_bcalpha = calibration(self.dlg_hydrograph_calibration.change_soil_bcalpha,self.dlg_hydrograph_calibration.calibrate_soil_bcalpha)
        soil_bclamda = calibration(self.dlg_hydrograph_calibration.change_soil_bclambda,self.dlg_hydrograph_calibration.calibrate_soil_bclambda)
        unsaturated_vgm = calibration(self.dlg_hydrograph_calibration.change_unsaturated_vgm,self.dlg_hydrograph_calibration.calibrate_unsaturated_vgm)
        unsaturated_bceta = calibration(self.dlg_hydrograph_calibration.change_unsaturated_bceta,self.dlg_hydrograph_calibration.calibrate_unsaturated_bceta)
        unsaturated_bcalpha = calibration(self.dlg_hydrograph_calibration.change_unsaturated_bcalpha,self.dlg_hydrograph_calibration.calibrate_unsaturated_bcalpha)
        usaturated_gdalpha = calibration(self.dlg_hydrograph_calibration.change_unsaturated_gdalpha,self.dlg_hydrograph_calibration.calibrate_unsaturated_gdalpha)
        
        
        
        #Change inputs if "Change" has selected
        self.change_base_inputs_calibration_hydrograph([vertical,average,saturated,initial,maximum,fraction,width,length,manning,slope,
            water_depth,soil_saturated,soil_or,soil_vgalpha,soil_vgn,soil_vgm,soil_bcalpha,soil_bclamda,unsaturated_vgm,unsaturated_bceta,unsaturated_bcalpha,usaturated_gdalpha])
        
        #Create dictionary
        if vertical == "calibrate":
            dictionary["vertical"] = [float(self.dlg_hydrograph_calibration.min_vertical.text()),float(self.dlg_hydrograph_calibration.max_vertical.text())]
            
        if average == "calibrate":
            dictionary["average"] = [float(self.dlg_hydrograph_calibration.min_average.text()),float(self.dlg_hydrograph_calibration.max_average.text())]
        
        if saturated == "calibrate":
            dictionary["saturated"] = [float(self.dlg_hydrograph_calibration.min_saturated.text()),float(self.dlg_hydrograph_calibration.max_saturated.text())]
        
        if initial == "calibrate":
            dictionary["initial"] = [float(self.dlg_hydrograph_calibration.min_initial.text()),float(self.dlg_hydrograph_calibration.max_initial.text())]
        
        if maximum == "calibrate":
            dictionary["maximum"] = [float(self.dlg_hydrograph_calibration.min_maximum.text()),float(self.dlg_hydrograph_calibration.max_maximum.text())]
        
        if fraction == "calibrate":
            dictionary["fraction"] = [float(self.dlg_hydrograph_calibration.min_fraction.text()),float(self.dlg_hydrograph_calibration.max_fraction.text())]
        
        if width == "calibrate":
            dictionary["width"] = [float(self.dlg_hydrograph_calibration.min_width.text()),float(self.dlg_hydrograph_calibration.max_width.text())]
        
        if length == "calibrate":
            dictionary["length"] = [float(self.dlg_hydrograph_calibration.min_length.text()),float(self.dlg_hydrograph_calibration.max_length.text())]
        
        if manning == "calibrate":
            dictionary["manning"] = [float(self.dlg_hydrograph_calibration.min_manning.text()),float(self.dlg_hydrograph_calibration.max_manning.text())]
        
        if slope == "calibrate":
            dictionary["slope"] = [float(self.dlg_hydrograph_calibration.min_slope.text()),float(self.dlg_hydrograph_calibration.max_slope.text())]
        
        
        
