    def modify_inputs_calibration(self,extension, row, column, new_value):
        """Method to modify inputs in calibration"""
        filepath = str(Path(self.dlg_base.working_directory_vfsmod.text()+f"/inverse/inputs/inverse.{extension}"))
        with open(filepath, 'r') as file:
            lineas = file.readlines()
        numbers_str = lineas[row]
        # Use regex to find all numbers in the string
        matches = re.findall(r'\S+', numbers_str)
        # Replace the specific number at the given index
        matches[column] = str(new_value)
        # Rebuild the string by replacing only the specific number
        lineas[row] = re.sub(r'\S+', lambda m, it=iter(matches): next(it), numbers_str, count=len(matches))
        with open(filepath, 'w') as archivo:
            for i in lineas:
                archivo.write(i)
    
    def change_base_inputs_calibration_hydrograph(self,inputs):
        """Method to change the inputs in the calibration of hydrograph if change is selected"""
        #vertical
        if inputs[0]=="change":
            self.modify_inputs_calibration("iso",0,0,self.dlg_hydrograph_calibration.new_vertical.text())
        #average
        if inputs[1]=="change":
            self.modify_inputs_calibration("iso",0,1,self.dlg_hydrograph_calibration.new_average.text())
        #saturated
        if inputs[2]=="change":
            self.modify_inputs_calibration("iso",0,2,self.dlg_hydrograph_calibration.new_saturated.text())
        #initial
        if inputs[3]=="change":
            self.modify_inputs_calibration("iso",0,3,self.dlg_hydrograph_calibration.new_initial.text())
        #maximum
        if inputs[4]=="change":
            self.modify_inputs_calibration("iso",0,4,self.dlg_hydrograph_calibration.new_maximum.text())
        #fraction
        if inputs[5]=="change":
            self.modify_inputs_calibration("iso",0,5,self.dlg_hydrograph_calibration.new_fraction.text())
        #width
        if inputs[6]=="change":
            self.modify_inputs_calibration("ikw",1,0,self.dlg_hydrograph_calibration.new_width.text())
