    def uncheck_length_spacing(self,parameter):
        """Method to check-uncheck the vegetation length or spacing because only one can be selected"""
        if parameter == "length" and self.dlg_base.design_length.isChecked(): 
            self.dlg_base.design_spacing.setChecked(False)
        elif parameter == "spacing" and self.dlg_base.design_spacing.isChecked(): 
            self.dlg_base.design_length.setChecked(False)
        
    def run_vfsmod(self):
        """Method to run VFSMOD"""
        #If working directory doesnt exist then error
        if not os.path.exists(self.working_directory):
            self.warning_message(f"{self.working_directory} folder does not exist. Please select a correct working directory.")
            return
        #Variable to end execution
        self.end_execution = False
        
        #Error handling
        self.error_handling_vfsmod()
        
        if self.end_execution:
            return
        
        #Folder creation
        self.folder_creation_vfsmod()
        
        #First we create the .prj file
        self.create_prj_file()
        
        #The hietograph file with this version of the executable creates .irn file with one more rain steps and it gets error
        #self.correct_irn_file(self.obtain_direction_vfsmod(self.dlg_base.line_storm.text()))
        
        #Update the number of pesticides that are in ikw file, just in case
        self.update_ikw_pesticide()
        
        #We update the bat for the execution fo VFSMOD
        self.update_bat_vfsmod()
        
        #Execute bat
        #In windows
        if sys.platform.startswith("win"):
            resultado = subprocess.run([str(Path(self.plugin_directory+"/executables/execution.bat"))],
                capture_output=True, 
                text=True, 
                shell=True)
        #In mac
        elif sys.platform.startswith("darwin"):
            script_path = Path("/Library/Application Support/vfsmod-gui") / "executables" / "execution.sh"
            uh_path = Path("/Library/Application Support/vfsmod-gui") / "executables" / "vfsm"

            # Unquarantine the 'vfsm' file (to allow it to be executed)
            try:
                subprocess.run(["xattr", "-d", "com.apple.quarantine", str(uh_path)], check=True)
            except subprocess.CalledProcessError:
                pass

            # Give execution permissions to the script and the executable
            #subprocess.run(["chmod", "755", str(script_path)], check=True)
            #subprocess.run(["chmod", "755", str(uh_path)], check=True)

            # Execute sh file
            resultado = subprocess.run([str(script_path)], capture_output=True, text=True)
        
        #Put warning
        if not "...FINISHED..." in resultado.stdout or "ERROR" in resultado.stdout:
            if str(resultado.stderr) != "":
                self.warning_message(str(resultado.stderr), courier = True)
            else:
                self.warning_message(str(resultado.stdout), courier = True)
        else:
            self.warning_message("VFS executed succesfully!")
        
        #If prj project is not in working directory then move it
        self.prj_project_save_working_directory()
        
        #Check if VFSMOD outputs exist
        self.check_vfsmod_output_exist()
        
        #Update value in design
        self.add_vfs_length_spacing()
    
    def correct_irn_file(self,path):
        """Method to correct the .irn file (the number of steps)"""
        #Open file
        with open(path, "r") as archivo:
            lineas = archivo.readlines()
        #Calculate the number of steps in hietograph
        number_steps = 0
        for i in lineas:
            try:
                float(i.strip().split(" ")[0]) #first number of the line
                number_steps += 1
            except:
                pass
        number_steps -=1
        #Add to the text
        splits = lineas[0].split(" ")
        for k,i in enumerate(splits):
            try:
                float(i)
                splits[k] = str(number_steps)
                break
            except:
                pass
        lineas[0] = " ".join(splits)
        #Save the file
        contenido = ""
        for i in lineas:    
            contenido+=f"{i}"
        with open(path, 'w') as archivo:
            archivo.write(contenido)
    
