    def warning_message(self,message, courier = False):
        """Method to put a warning message"""
        #Put text
        self.dlg_warning_message.warning.setText(message)
        # Change font type to Courier
        if courier:
            courier_font = QFont("Courier")
            courier_font.setStyleHint(QFont.Monospace)  # Asegura el estilo monoespaciado
            courier_font.setFixedPitch(True)            # Garantiza el espaciado fijo
            courier_font.setPointSize(10)               # Ajusta el tamaño de fuente, si es necesario

            # Aplicar la fuente al QLabel
            self.dlg_warning_message.warning.setFont(courier_font) 
        else:
            courier_font = QFont("Georgia")
            courier_font.setStyleHint(QFont.Monospace)  # Asegura el estilo monoespaciado
            courier_font.setFixedPitch(True)            # Garantiza el espaciado fijo
            courier_font.setPointSize(12)               # Ajusta el tamaño de fuente, si es necesario

            # Aplicar la fuente al QLabel
            self.dlg_warning_message.warning.setFont(courier_font)
            
        #Put to the front
        self.dlg_warning_message.raise_()
        self.dlg_warning_message.activateWindow()
        #Adjust size
        self.dlg_warning_message.adjustSize()
        #Show the dialog
        self.dlg_warning_message.show()
        
    def update_bat_uh(self):
        """Metod to update bat for the execution of UH"""
        
        #In windows
        if sys.platform.startswith("win"):
            f = open(str(Path(self.plugin_directory+"/executables/execution.bat")),"w+")
            linea_uno = "cd {}".format(f'"{os.path.dirname(os.path.normpath(self.obtain_direction_vfsmod(self.dlg_base.uh_file.text())))}"')
            linea_dos = f'"{str(Path(self.plugin_directory+"/executables/uh"))}" {os.path.normpath(os.path.basename(self.dlg_base.uh_file.text()))}'
            linea_tres = "Pause"
            f.write("{} \n".format(linea_uno))
            f.write("{} \n".format(linea_dos))
            #f.write("{} \n".format(linea_tres))
            f.close()
        
        #In mac
        elif sys.platform.startswith("darwin"):
            with open(str(Path("/Library/Application Support/vfsmod-gui"+"/executables/execution.sh")), "w", newline="\n") as f:
                linea_uno = "#!/bin/bash\n"
                linea_dos = "cd {}".format(f'"{os.path.dirname(os.path.normpath(self.obtain_direction_vfsmod(self.dlg_base.uh_file.text())))}"')
                linea_tres = f'"{str(Path("/Library/Application Support/vfsmod-gui"+"/executables/uh"))}" {os.path.normpath(os.path.basename(self.dlg_base.uh_file.text()))}'
                f.write("{} \n".format(linea_uno))
                f.write("{} \n".format(linea_dos))
                f.write("{} \n".format(linea_tres))
                f.close()
            
            
    def obtain_direction_vfsmod(self,direction):
        """Method to obtain the absolute path direction. The difference with the other is that
        here is respect to the working directory of vfsmod"""
        carpeta = self.dlg_base.working_directory_vfsmod.text()
        direction = str(Path(direction.replace("\\","/")))
        if not os.path.isabs(direction): #relative path
            return os.path.normpath(os.path.join(carpeta, direction))
        else: #absolute path
            return os.path.normpath(direction)
            
