    def create_iwq_file(self, close =False):
        """Mehtod to crete the .iwq file"""
        #Inputs
        if self.dlg_water_quality.check_direct.isChecked(): direct_input = 0
        else: direct_input = 1
        IWQPRO = self.dlg_water_quality.trapping_equation.currentIndex()+1
        a = self.dlg_water_quality.equation_a.text()
        b = self.dlg_water_quality.equation_b.text()
        c = self.dlg_water_quality.equation_c.text()
        d = self.dlg_water_quality.equation_d.text()
        e = self.dlg_water_quality.equation_e.text()
        vkoc = self.dlg_water_quality.line_koc_1.text()
        vkd = self.dlg_water_quality.line_kd_1.text()
        oc = self.dlg_water_quality.line_oc_1.text()
        clay = self.dlg_water_quality.line_clay.text()
        days = self.dlg_water_quality.days.text()
        half_life = self.dlg_water_quality.half_life_1.text()
        field_capacity = self.dlg_water_quality.field_capacity.text()
        mass = self.dlg_water_quality.mass_1.text()
        thickness = self.dlg_water_quality.thickness.text()
        dgld = self.dlg_water_quality.dispersion_1.text()
        dgmres0 = self.dlg_water_quality.remobilized_1.text()
        idg = int(self.dlg_water_quality.calculation.currentIndex())
        imob = self.dlg_water_quality.imob.currentIndex()+1
        number_pesticides = int(self.dlg_water_quality.number_pesticides.text())
        
        #Create file
        iwq_file =self.obtain_direction_prj(self.dlg_base.line_water.text())
        #If directory doesn't exist then create it
        directory = os.path.dirname(iwq_file)
        if not os.path.exists(directory):
            os.makedirs(directory)
        with open(iwq_file, 'w') as archivo:
            linea_uno = f"{IWQPRO} {a} {b} {c} {d} {e} ;IWQPRO CSAB(I)"
            if direct_input == 1:
                linea_dos = f"{direct_input} {vkoc} {oc} "
                for p in range(number_pesticides-1):
                    linea_dos += f"{getattr(self.dlg_water_quality, f'line_koc_{p+2}').text()} "
                linea_dos += "                     ; IKD (Kd or Koc) (%OC) (repeat Koc or Kd for j species)"
            else:
                linea_dos = f"{direct_input} {vkd} "
                for p in range(number_pesticides-1):
                    linea_dos += f"{getattr(self.dlg_water_quality, f'line_kd_{p+2}').text()} "
                linea_dos += "                     ; IKD (Kd or Koc) (%OC) (repeat Koc or Kd for j species)"
                    
            linea_tres = f"{clay}			; %Clay content in field soil"
            linea_cuatro = f"{idg} IDG"
            
            #If IDG = 0 then we put some values by default
            if idg == 0:
                linea_cinco = f"{1} {100} {0.25} {mass} {thickness} {0.05} {dgmres0} "
            else:
                linea_cinco = f"{days} {half_life} {field_capacity} {mass} {thickness} {dgld} {dgmres0} "
            for p in range(number_pesticides-1):
                #If IDG = 0 then we put some values by default
                if idg == 0:
                    linea_cinco += f"{100} {getattr(self.dlg_water_quality, f'mass_{p+2}').text()} {0.05} {getattr(self.dlg_water_quality, f'remobilized_{p+2}').text()} "
                else:
                    linea_cinco += f"{getattr(self.dlg_water_quality, f'half_life_{p+2}').text()} {getattr(self.dlg_water_quality, f'mass_{p+2}').text()} {getattr(self.dlg_water_quality, f'dispersion_{p+2}').text()} {getattr(self.dlg_water_quality, f'remobilized_{p+2}').text()} "
            linea_cinco += "; ndgday dgHalf FC dgPin dgML dgLD dgmres0 (repeat {dgHalf,dgPIN,dgLD,dgmres0}_j for j species)"
            linea_seis = ""
            #If IDG = 0 then we put some values by default
            if idg == 0:
                rows = 1
            else:
                rows = self.dlg_water_quality.tableWidget.rowCount()
            for row in range(rows):
                item = self.dlg_water_quality.tableWidget.item(row, 1)
                value = item.text()
                #If IDG = 0 then we put some values by default
                if idg == 0:
                    linea_seis += f"{25} "
                else:
                    linea_seis += f"{value} "
            linea_seis += "(dgT(i),i=1,ndgday) (Celsius)"
            
            linea_siete = ""
            for row in range(rows):
                item = self.dlg_water_quality.tableWidget.item(row, 2)
                value = item.text()
                #If IDG = 0 then we put some values by default
                if idg == 0:
                    linea_siete += f"{0.25} "
                else:
                    linea_siete += f"{value} "
            linea_siete += "(dgTheta(i),i=1,ndgday (-)"
            linea_ocho = f"{imob}                                       ; IMOB\n"
            if number_pesticides>1 and idg !=0:
                #Add molar
                for p in range(number_pesticides):
                    linea_ocho += f"{getattr(self.dlg_degradation_data, f'pesticide_{p+1}_molar_mass').text()} "
                linea_ocho += "                            ; Mj molar mass of compounds (g/mol)\n"
                
                table = self.dlg_degradation_data.table_degradations
                num_rows = table.rowCount()
                #Add degradation
                for row in range(num_rows):
                    for col in range(num_rows):
                        # Obtener el item de la celda en la posición (row, col)
                        item = table.item(row, col)
                        value = item.text() if item else ""
                        linea_ocho += f"{value} "
                    if row == 0:
                        linea_ocho += "                            ; fij molar formation fraction matrix {jxj}"
                    linea_ocho += "\n"
            linea_nueve = "\n------------------------------------------------------------------\nIWQPRO    : Pesticide trapping: 1=Sabbagh;2= Sabbagh(refit);3=mech.mass bal.;4=Chen\nCSAB(I)   : Coefficients for refitted Sabbagh equation (used when IWQPRO=2)\nIKD       : Sorption type: 0, Kd(L/Kg); 1, Koc (L/Kg)\nKd(j) Koc(j): Sorption coefficient (j species) as distribution Kd (IKD= 0) or Koc (IKD=1) (L/Kg)\n%OC       : Source soil organic carbon, only read when IKD=1 (Koc) (%)\nIDG       : Degradation type: 1: EU-FOCUS k=Kref.k(T).k(theta); 2: US-EPA k=Kref;\n            3: k=Kref.k(T);4: k=Kref.k(1theta; 0: No degradation (no more inputs are read)\nndgday    : no. of days (i) between events (d)\ndgHalf(j) : t0.5, pesticide half-life (d), kref=Ln2/t0.5\nFC        : top soil field capacity (m3/m3). This can be taken from FOCUS R1-R4 scenario\n            parameters used by the PRZM model\ndgPin(j)  : Pin, pesticide mass entering filter for event over source area (mg/m2)\ndgML      : Surface mixing layer thickness (cm, standard= 2cm PRZM)\ndgLD(j)   : lambda, dispersion length of chemical (m). This can be taken as  \n            0.05m from FOCUS-Pearl (Default)\ndgmres0(j): Pesticide residues (i species) on VFS surface (mixing layer) when event starts (mg/m2)\ndgT(i)    : T, daily air temperatures (C) for period between events, PRZM weather\ndgTheta(i): theta, Topsoil daily volumetric moisture (-) for period between events\nIMOB      : Residues remobilization: 1(or none): partial (recomm); 2:full; 3:no remob.\nMj        : Molar mass of compounds (g/mol) (only read when number of compounds is j>1)\nfij       : matrix of molar formation fractions between compounds {jxj} (when number of compounds is j>1)"
            
            archivo.write(f"{linea_uno}\n")
            archivo.write(f"{linea_dos}\n")
            archivo.write(f"{linea_tres}\n")
            
            if idg !=0:
                archivo.write(f"{linea_cuatro}\n")
                archivo.write(f"{linea_cinco}\n")
                archivo.write(f"{linea_seis}\n")
                archivo.write(f"{linea_siete}\n")
                archivo.write(f"{linea_ocho}\n")
            
            else:
                archivo.write(f"{linea_cuatro}\n")
                archivo.write(f"{linea_cinco}\n")
                archivo.write(f"{linea_seis}\n")
                archivo.write(f"{linea_siete}\n")
                archivo.write(f"{linea_ocho}\n")
            
            archivo.write(f"{linea_nueve}\n")
        
        #Update ikw pesticide
        self.update_ikw_pesticide()
        
        #Close dialog
        if close:
            self.dlg_water_quality.close()
    
    def update_ikw_pesticide(self):
        """Method to update ikw when ikw file created"""
        ikw_file =self.obtain_direction_prj(self.dlg_base.line_overland.text())
        if os.path.exists(ikw_file):
            #See if pesticide option is selected
            if self.dlg_base.water_quality.isChecked():execute_pesticide = int(self.dlg_water_quality.number_pesticides.text())
            else: execute_pesticide = 0
            with open(ikw_file, 'r') as file:
                lineas = file.readlines()
            row = 3+int(lineas[3])+1
            numbers_str = lineas[row]
            # Use regex to find all numbers in the string
            matches = re.findall(r'\S+', numbers_str)
            # Replace the specific number at the given index
            matches[0] = str(execute_pesticide)
            # Rebuild the string by replacing only the specific number
            lineas[row] = re.sub(r'\S+', lambda m, it=iter(matches): next(it), numbers_str, count=len(matches))
            with open(ikw_file, 'w') as archivo:
                for i in lineas:
                    archivo.write(i)
    
